// Advanced Bracket Validation Examples
// Run with: cargo run --example advanced_demo

use brackets_basic::{validate_brackets, BracketErrorKind};

fn main() {
    println!("🚀 Advanced Bracket Validation Examples\n");

    // ==============================================
    // Real-world programming examples
    // ==============================================
    println!("📝 Real Programming Examples:");

    let code_examples = vec![
        ("if (x > 0) { print(\"positive\"); }", true),
        ("array[index] = { key: values[i] };", true),
        ("func(a, [b, c], {d: e})", true),
        (
            "JSON: {\"users\": [{\"name\": \"Alice\"}, {\"name\": \"Bob\"}]}",
            true,
        ),
        ("function add(a, b) { return a + b; }", true),
        // Error cases
        ("if (x > 0 { print(\"missing closing paren\"); }", false),
        ("array[index = { key: values[i] };", false),
        ("func(a, [b, c}, {d: e})", false),
    ];

    for (code, should_be_valid) in code_examples {
        let result = validate_brackets(code);
        let is_valid = result.is_ok();
        let status = if is_valid == should_be_valid {
            "✅"
        } else {
            "⚠️"
        };

        match result {
            Ok(()) => println!("  {} '{}' → Valid", status, code),
            Err(e) => println!(
                "  {} '{}' → Error: {}",
                status,
                code,
                explain_error(&e.kind)
            ),
        }
    }

    // ==============================================
    // Edge cases and tricky examples
    // ==============================================
    println!("\n🎯 Edge Cases and Tricky Examples:");

    let tricky_examples = vec![
        "((()))",                              // Deeply nested same type
        "()()()()()()()(",                     // Many pairs + one unclosed
        "([{}])",                              // All three types nested
        "{[()()()()()]]}",                     // Mixed nesting with repeats
        "text(more[text{inside}more]text)end", // Real text mixed in
        "(((",                                 // Multiple unclosed (reports first)
        ")))",                                 // Multiple unexpected (reports first)
        "([)]",                                // Classic wrong order
        "({[}])",                              // Complex wrong order
    ];

    for example in tricky_examples {
        match validate_brackets(example) {
            Ok(()) => println!("  ✅ '{}' → Valid", example),
            Err(e) => println!(
                "  ❌ '{}' → Error at pos {}: {}",
                example,
                e.index,
                explain_error(&e.kind)
            ),
        }
    }

    // ==============================================
    // Performance demonstration
    // ==============================================
    println!("\n⚡ Performance Test:");

    // Create a large valid string
    let large_valid = "(".repeat(1000) + &")".repeat(1000);
    let start = std::time::Instant::now();
    let result = validate_brackets(&large_valid);
    let duration = start.elapsed();

    println!(
        "  Large string (2000 chars): {:?} in {:?}",
        result.is_ok(),
        duration
    );

    // Create a large invalid string (error at the end)
    let large_invalid = "(".repeat(1000) + &")".repeat(999) + "]";
    let start = std::time::Instant::now();
    let result = validate_brackets(&large_invalid);
    let duration = start.elapsed();

    match result {
        Ok(()) => println!("  Large invalid: Valid (unexpected!)"),
        Err(e) => println!(
            "  Large invalid: Error at pos {} in {:?}",
            e.index, duration
        ),
    }

    // ==============================================
    // Interactive challenge
    // ==============================================
    println!("\n🎲 Can you predict these results?");

    let challenge_cases = vec!["()()()(", "([)]", "{[(])}", "(((", ")))", ""];

    for case in &challenge_cases {
        println!("  '{}' → ?", case);
    }

    println!("\nPress Enter to see answers...");
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();

    println!("Answers:");
    for case in &challenge_cases {
        match validate_brackets(case) {
            Ok(()) => println!("  '{}' → ✅ Valid", case),
            Err(e) => println!("  '{}' → ❌ Error: {}", case, explain_error(&e.kind)),
        }
    }
}

fn explain_error(kind: &BracketErrorKind) -> String {
    match kind {
        BracketErrorKind::UnexpectedClosing { found } => {
            format!("Unexpected '{}' (no matching opener)", found)
        }
        BracketErrorKind::MismatchedPair { expected, found } => {
            format!("Expected '{}' but found '{}'", expected, found)
        }
        BracketErrorKind::UnclosedOpenings { expected, .. } => {
            format!("Unclosed bracket (expected '{}')", expected)
        }
    }
}

// Algorithm Analysis: Why Stack is Perfect for Bracket Validation
// Run with: cargo run --example algorithm_analysis

use brackets_basic::{validate_brackets, BracketErrorKind};

fn main() {
    println!("🧠 Algorithm Analysis: Why Stack is Perfect for Bracket Validation\n");

    // ==============================================
    // The Core Insight
    // ==============================================
    println!("🎯 The Core Insight:");
    println!("Bracket validation is fundamentally about MATCHING PAIRS in NESTED STRUCTURES");
    println!("  • When we see '(' we PROMISE to see ')' later");
    println!("  • When we see '[' we PROMISE to see ']' later");
    println!("  • When we see '{{' we PROMISE to see '}}' later");
    println!("  • The LAST promise made must be the FIRST promise fulfilled (LIFO = Stack!)");

    // ==============================================
    // Why other data structures don't work
    // ==============================================
    println!("\n❌ Why Other Data Structures Don't Work:");

    println!("\n📋 Array/Vec (without stack behavior):");
    println!("  Example: '([)]'");
    println!("  • Array would store: [')', ']']");
    println!("  • When we see ')', which one to check? First? Last?");
    println!("  • No clear ordering rule → Wrong!");

    println!("\n🔄 Queue (FIFO):");
    println!("  Example: '([)]'");
    println!("  • Queue stores: [')' ← first, ']' ← last]");
    println!("  • When we see ')', check first in queue → ')' ✅");
    println!("  • When we see ']', check first in queue → ']' ✅");
    println!("  • But this is WRONG! '([)]' should be invalid!");

    println!("\n📚 Stack (LIFO):");
    println!("  Example: '([)]'");
    println!("  • Stack stores: [bottom ')' ... top ']']");
    println!("  • When we see ')', check top of stack → ']' ≠ ')' ❌");
    println!("  • Correctly identifies the error!");

    // ==============================================
    // Step-by-step comparison
    // ==============================================
    println!("\n🔍 Step-by-Step Comparison with '([)]':");

    demonstrate_with_different_structures("([)]");

    // ==============================================
    // Time and Space Complexity
    // ==============================================
    println!("\n⚡ Time and Space Complexity:");
    println!("  Time: O(n) - visit each character exactly once");
    println!("  Space: O(n) - worst case: all opening brackets like '((((('");
    println!("  This is OPTIMAL - you can't do better than O(n) time!");

    // ==============================================
    // Real-world applications
    // ==============================================
    println!("\n🌍 Real-World Applications of This Algorithm:");

    let applications = vec![
        ("Code Editors", "Syntax highlighting, auto-completion"),
        ("Compilers", "Parsing programming languages"),
        ("JSON/XML Parsers", "Validating nested structures"),
        (
            "Mathematical Expression Evaluators",
            "Parsing (2 + (3 * 4))",
        ),
        ("HTML/XML Validators", "Matching <div> with </div>"),
        ("Shell Script Parsers", "Matching quotes and brackets"),
    ];

    for (app, desc) in applications {
        println!("  • {}: {}", app, desc);
    }

    // ==============================================
    // Extension possibilities
    // ==============================================
    println!("\n🚀 How to Extend This Algorithm:");
    println!("  • XML Tags: <div> must match </div>");
    println!("  • String Quotes: \"hello\" and 'world'");
    println!("  • Code Blocks: if/endif, begin/end");
    println!("  • Custom Delimiters: /* comment */");

    test_extension_idea();
}

fn demonstrate_with_different_structures(input: &str) {
    println!("Testing: '{}'", input);

    // Simulate different approaches
    println!("\n  📚 Stack Approach (CORRECT):");
    let mut stack = Vec::new();

    for (i, ch) in input.char_indices() {
        match ch {
            '(' => {
                stack.push(')');
                println!("    {}. '{}' → push ')'  Stack: {:?}", i, ch, stack);
            }
            '[' => {
                stack.push(']');
                println!("    {}. '{}' → push ']'  Stack: {:?}", i, ch, stack);
            }
            '{' => {
                stack.push('}');
                println!("    {}. '{}' → push '}}'  Stack: {:?}", i, ch, stack);
            }
            ')' | ']' | '}' => {
                if let Some(expected) = stack.pop() {
                    if ch == expected {
                        println!(
                            "    {}. '{}' → pop '{}'   Stack: {:?} ✅ Match!",
                            i, ch, expected, stack
                        );
                    } else {
                        println!(
                            "    {}. '{}' → pop '{}'   Stack: {:?} ❌ Expected '{}', got '{}'",
                            i, ch, expected, stack, expected, ch
                        );
                        break;
                    }
                } else {
                    println!("    {}. '{}' → empty stack ❌ Unexpected closing", i, ch);
                    break;
                }
            }
            _ => {}
        }
    }

    // Now run actual validator
    match validate_brackets(input) {
        Ok(()) => println!("  ✅ Actual result: Valid"),
        Err(e) => println!("  ❌ Actual result: Error - {}", explain_error(&e.kind)),
    }
}

fn test_extension_idea() {
    println!("\n🧪 Extension Example - XML-style Tags:");
    println!("Imagine extending the algorithm for <tag></tag> matching:");

    let xml_examples = vec![
        "<div></div>",
        "<p><b>text</b></p>",
        "<div><p></div></p>", // Wrong nesting
    ];

    for example in xml_examples {
        println!(
            "  '{}' → Would need modified algorithm for tag names",
            example
        );
    }

    println!("  The core stack principle still applies!");
    println!("  Stack would store: [(tag_name, position), ...]");
}

fn explain_error(kind: &BracketErrorKind) -> String {
    match kind {
        BracketErrorKind::UnexpectedClosing { found } => {
            format!("Unexpected '{}' (no matching opener)", found)
        }
        BracketErrorKind::MismatchedPair { expected, found } => {
            format!("Expected '{}' but found '{}'", expected, found)
        }
        BracketErrorKind::UnclosedOpenings { expected, .. } => {
            format!("Unclosed bracket (expected '{}')", expected)
        }
    }
}

// Let me show you how to improve the brackets.rs documentation
// This demonstrates applying Rust documentation standards to your existing code

use brackets_basic::{validate_brackets, BracketErrorKind};

fn main() {
    println!("📚 Rust Documentation Standards Applied to Brackets Validation\n");

    // Let's test the documented functionality
    demonstrate_validation_with_documentation();
}

fn demonstrate_validation_with_documentation() {
    println!("🎯 Testing the documented behavior:\n");

    // Test cases that would be in the documentation
    let test_cases = vec![
        ("", "Empty string (edge case)"),
        ("()", "Simple parentheses"),
        ("[]", "Simple square brackets"),
        ("{}", "Simple curly braces"),
        ("([{}])", "Nested all types"),
        ("hello(world[test{data}more]end)", "Mixed with text"),
        (")", "Unexpected closing"),
        ("(]", "Mismatched pair"),
        ("(((", "Unclosed openings"),
    ];

    for (input, description) in test_cases {
        match validate_brackets(input) {
            Ok(()) => println!("✅ '{}' → Valid ({})", input, description),
            Err(error) => {
                let error_type = match error.kind {
                    BracketErrorKind::UnexpectedClosing { .. } => "UnexpectedClosing",
                    BracketErrorKind::MismatchedPair { .. } => "MismatchedPair",
                    BracketErrorKind::UnclosedOpenings { .. } => "UnclosedOpenings",
                };
                println!(
                    "❌ '{}' → {} at pos {} ({})",
                    input, error_type, error.index, description
                );
            }
        }
    }
}

