        );

        group.bench_with_input(
            BenchmarkId::new("memoized", iterations),
            iterations,
            |b, &iterations| {
                b.iter(|| {
                    let result = look_and_say_with_memo(black_box(input), iterations);
                    black_box(result.len())
                });
            },
