    for y in 0..grid.height() {
        print!("  ");
        for x in 0..grid.width() {
            let coord = (x, y).into();
            let symbol = match grid.get(coord) {
                Some(true) => "🟡",  // On
                Some(false) => "⚫", // Off
                None => "❓",        // Error
            };
            print!("{}", symbol);
        }
        println!();
    }
}

