    #[test]
    fn test_16_bit_overflow_behavior() {
        // Test that Rust handles u16 overflow correctly
        let max_val = u16::MAX; // 65535
        let result = max_val.wrapping_add(1); // Should wrap to 0
        assert_eq!(result, 0);
    }
}

