}

impl PanicHandler {
    fn new() -> Self {
        Self {
            panic_count: std::sync::atomic::AtomicUsize::new(0),
        }
    }
    
    fn log_panic(&self, message: &str) {
        let count = self.panic_count.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        println!("PANIC #{}: {}", count + 1, message);
    }
}

