fn process_line(line: &str) -> AnyhowResult<()> {
    let parts: Vec<&str> = line.split(',').collect();
    if parts.len() != 2 {
        return Err(Box::new(SimpleError::new(format!(
            "Invalid format: expected 'key,value', got '{}'",
            line
        ))));
    }

    let key = parts[0].trim();
    let value = parts[1]
        .trim()
        .parse::<i32>()
        .with_context(|| format!("Invalid number: '{}'", parts[1]))?;

    println!("Key: {}, Value: {}", key, value);
    Ok(())
}

fn process_user_input(input: &str) -> AnyhowResult<()> {
    let lines: Vec<&str> = input.lines().collect();
    if lines.is_empty() {
        return Err(Box::new(SimpleError::new("Input is empty".to_string())));
    }

    for (line_num, line) in lines.iter().enumerate() {
        process_line(line).map_err(|e| {
            anyhow::anyhow!("Failed to process line {} of input: {}", line_num + 1, e)
        })?;
    }

    println!("Successfully processed {} lines", lines.len());
    Ok(())
}

// Example functions demonstrating thiserror-style error handling
impl Config {
    #[allow(dead_code)]
    pub fn load_from_file(path: &str) -> Result<Self, ConfigError> {
        let content = std::fs::read_to_string(path)?;
        Self::parse(&content)
    }

    pub fn parse(content: &str) -> Result<Self, ConfigError> {
        let mut host = None;
        let mut port = None;

        for (line_num, line) in content.lines().enumerate() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            if let Some((key, value)) = parse_key_value(line) {
                match key.as_str() {
                    "host" => {
                        if value.is_empty() {
                            return Err(ConfigError::Validation {
                                field: "host".to_string(),
                                reason: "Host cannot be empty".to_string(),
                            });
                        }
                        host = Some(value);
                    }
                    "port" => {
                        port = Some(value.parse::<u16>().map_err(|_| ConfigError::Parse {
                            line: line_num + 1,
                            message: format!("Invalid port number: {}", value),
                        })?);
                    }
                    _ => {
                        return Err(ConfigError::Parse {
                            line: line_num + 1,
                            message: format!("Unknown configuration key: {}", key),
                        });
                    }
                }
            } else {
                return Err(ConfigError::Parse {
                    line: line_num + 1,
                    message: "Invalid key=value format".to_string(),
                });
            }
        }

        Ok(Config {
            host: host.ok_or_else(|| ConfigError::Config {
                message: "Missing required field: host".to_string(),
            })?,
            port: port.unwrap_or(8080),
        })
    }
}

fn parse_key_value(line: &str) -> Option<(String, String)> {
    if let Some(pos) = line.find('=') {
        let key = line[..pos].trim().to_string();
        let value = line[pos + 1..].trim().to_string();
        Some((key, value))
    } else {
        None
    }
}

