}

// Pattern 3: Conditional Processing
fn process_data_conditionally(
    data: &str,
    options: ProcessOptions,
) -> Result<ProcessedData, ProcessError> {
    parse_raw_data(data)
        .and_then(|raw| {
            if options.validate {
                validate_data(&raw).map(|_| raw)
            } else {
                Ok(raw)
            }
        })
        .and_then(|raw| {
            if options.transform {
                transform_data(raw)
            } else {
                Ok(ProcessedData::from(raw))
            }
        })
        .map(|processed| {
            if options.normalize {
                processed.normalize()
            } else {
                processed
            }
        })
}

fn parse_raw_data(data: &str) -> Result<RawData, ProcessError> {
    Ok(RawData {
        content: data.to_string(),
    })
}

fn validate_data(raw: &RawData) -> Result<(), ProcessError> {
    if raw.content.is_empty() {
        Err(ProcessError::ValidationError("Empty data".to_string()))
    } else {
        Ok(())
