#[allow(dead_code)]
enum FileProcessingError {
    FileNotFound { path: String },
    PermissionDenied { path: String },
    InvalidFormat { expected: String, actual: String },
    ProcessingFailed { stage: String, reason: String },
    OutputNotWritable { path: String },
    Io { source: String },
}

impl std::fmt::Display for FileProcessingError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FileProcessingError::FileNotFound { path } => write!(f, "File not found: {}", path),
            FileProcessingError::PermissionDenied { path } => {
                write!(f, "Permission denied: {}", path)
            }
            FileProcessingError::InvalidFormat { expected, actual } => {
                write!(f, "Invalid format: expected {}, got {}", expected, actual)
            }
            FileProcessingError::ProcessingFailed { stage, reason } => {
                write!(f, "Processing failed at stage {}: {}", stage, reason)
            }
            FileProcessingError::OutputNotWritable { path } => {
                write!(f, "Output directory not writable: {}", path)
            }
            FileProcessingError::Io { source } => write!(f, "IO error: {}", source),
        }
    }
}

