            }
        }
        Err(e) => println!("Processing failed: {:?}", e),
    }

    // Clean up test files
    let _ = std::fs::remove_dir_all("input");
    let _ = std::fs::remove_dir_all("output");
    println!();

    println!("=== End of Day 34 Examples ===");
