// Performance Validation (Simple Version)
// Run with: cargo run --example performance_check

use mission1::Stack;
use std::time::Instant;

fn main() {
    println!("⚡ Performance Validation\n");

    // ==============================================
    // Test 1: Push performance scales linearly
    // ==============================================
    println!("📊 Test 1: Push Performance Scaling");

    let test_sizes = vec![1_000, 10_000, 100_000];

    for size in test_sizes {
        let start = Instant::now();

        let mut stack = Stack::new();
        for i in 0..size {
            stack.push(i);
        }

        let duration = start.elapsed();
        let ops_per_sec = size as f64 / duration.as_secs_f64();

        println!(
            "  {} pushes took {:?} ({:.0} ops/sec)",
            size, duration, ops_per_sec
        );
    }

    println!("✅ Push should scale roughly linearly (more items = proportionally more time)");

    // ==============================================
    // Test 2: Pop performance is constant
    // ==============================================
    println!("\n📊 Test 2: Pop Performance (should be constant time)");

    let mut stack = Stack::new();

    // Fill with lots of data
    for i in 0..100_000 {
        stack.push(i);
    }

    // Time individual pops
    let mut pop_times = Vec::new();
    for _ in 0..10 {
        let start = Instant::now();
        stack.pop();
        let duration = start.elapsed();
        pop_times.push(duration);
    }

    println!("Individual pop times:");
    for (i, time) in pop_times.iter().enumerate() {
        println!("  Pop {}: {:?}", i + 1, time);
    }

    println!("✅ Pop times should be roughly similar (O(1) - constant time)");

    // ==============================================
    // Test 3: Memory usage
    // ==============================================
    println!("\n💾 Test 3: Memory Efficiency");

    let mut stack = Stack::new();
    println!("Empty stack size: {} bytes", std::mem::size_of_val(&stack));

    // Add some items
    for i in 0..1000 {
        stack.push(i);
    }

    println!(
        "Stack with 1000 items: still {} bytes (items stored separately)",
        std::mem::size_of_val(&stack)
    );
    println!("✅ Stack struct itself is small (just holds a Vec)");

    println!("\n🏁 Performance validation complete!");
    println!("📝 For production code, use Criterion crate for precise benchmarks");
}

use mission1::Stack;

fn demonstrate_pop_ownership() {
    let mut stack = Stack::new();

    println!("=== Setting up the stack ===");
    stack.push(String::from("First"));
    stack.push(String::from("Second"));
    stack.push(String::from("Third"));
    println!("Stack after pushes: {:?}", stack);
    println!("Length: {}", stack.len());

    println!("\n=== Pop transfers ownership ===");

    // Pop the top item - we get ownership
    let popped1 = stack.pop().unwrap(); // Gets "Third"
    println!("Popped value: {}", popped1);
    println!("Stack after first pop: {:?}", stack);
    println!("Length: {}", stack.len());

    // We own 'popped1' now - we can do anything with it
    let modified = format!("{} (modified)", popped1);
    println!("We can modify our owned value: {}", modified);

    // Pop another
    let popped2 = stack.pop().unwrap(); // Gets "Second"
    println!("Popped value: {}", popped2);
    println!("Stack after second pop: {:?}", stack);

    // Pop the last one
    let popped3 = stack.pop().unwrap(); // Gets "First"
    println!("Popped value: {}", popped3);
    println!("Stack after third pop: {:?}", stack);

    // Try to pop from empty stack
    let empty_pop = stack.pop();
    println!("Pop from empty stack: {:?}", empty_pop);

    println!("\n=== All popped values are still owned by us ===");
    println!("popped1: {}", popped1);
    println!("popped2: {}", popped2);
    println!("popped3: {}", popped3);
    println!("The stack has NO access to these values anymore!");
}

fn main() {
    demonstrate_pop_ownership();
}

