    let found_ref = {
        let result = binary_search::search_slice(&data, &5);
        match result {
            Ok(idx) => Some(&data[idx]),
            Err(_) => None,
        }
    };

    assert_eq!(found_ref, Some(&5));

    // Test with iterator
    let range_refs: Vec<_> = {
        use search_iter::find_range;
        find_range(&data, &3, &7).collect()
    };

    assert_eq!(range_refs, [&3, &5, &7]);
}

