// Property-based tests with random data
#[test] // Cross-verification with std library
fn property_test_against_std_library() {
    use rand::{thread_rng, Rng};

    let mut rng = thread_rng();

    for _ in 0..100 {
        let mut data: Vec<i32> = (0..50).map(|_| rng.gen_range(-100..100)).collect();
        data.sort();

        let target = rng.gen_range(-100..100);

        let std_result = data.binary_search(&target);
        let our_result = binary_search::search_slice(&data, &target);

        match (std_result, our_result) {
            (Ok(std_idx), Ok(our_idx)) => {
                // Both found - values should be equal (index might differ for duplicates)
                assert_eq!(data[std_idx], data[our_idx]);
            }
            (Err(std_idx), Err(our_idx)) => {
                // Both not found - insertion indices should match
                assert_eq!(std_idx, our_idx);
            }
            _ => panic!(
                "Results should match: std={:?}, ours={:?}",
                std_result, our_result
            ),
        }
    }
}

//! Demo example for Mission 4: Singly Linked List
//!
//! This example demonstrates both SimpleLinkedList and RcLinkedList implementations,
//! showing their different use cases and ownership patterns.

use mission4::{RcLinkedList, SimpleLinkedList};

fn main() {
    println!("🦀 Mission 4: Singly Linked List Demo");
    println!("=====================================\n");

    demo_simple_linked_list();
    println!();
    demo_rc_linked_list();
    println!();
    demo_comparison();
}

fn demo_simple_linked_list() {
    println!("📦 SimpleLinkedList (Box-based ownership)");
    println!("------------------------------------------");

    let mut list = SimpleLinkedList::new();

    // Push some elements
    println!("Pushing elements: 3, 2, 1");
    list.push_front(3);
    list.push_front(2);
    list.push_front(1);

    println!("List length: {}", list.len());
    println!("List display: {}", list);

    // Peek at front
    if let Some(front) = list.peek_front() {
        println!("Front element: {}", front);
    }

    // Modify front element
    if let Some(front) = list.peek_front_mut() {
        *front = 42;
        println!("Modified front element to: {}", front);
    }

    // Iterate and collect
    println!("All elements:");
    for (i, value) in list.iter().enumerate() {
        println!("  [{}]: {}", i, value);
    }

    // Pop elements
    println!("Popping elements:");
    while let Some(value) = list.pop_front() {
        println!("  Popped: {}", value);
    }

    println!("List is now empty: {}", list.is_empty());
}

fn demo_rc_linked_list() {
