//! # Mission 4: Singly Linked List - Interior Mutability and Ownership
//!
//! This library implements singly linked lists in Rust, demonstrating why this fundamental
//! data structure presents unique challenges in Rust's ownership system. We explore multiple
//! implementation approaches, from simple Box-based ownership to advanced patterns using
//! reference counting and interior mutability.
//!
//! ## Requirements Fulfilled
//!
//! - **REQ-1**: Basic linked list structure with owned pointers
//! - **REQ-2**: Interior mutability with `Rc<RefCell<T>>` patterns
//! - **REQ-3**: Core list operations (push, pop, peek)
//! - **REQ-4**: Safe iteration patterns
//! - **REQ-5**: Memory management comparisons
//! - **REQ-6**: Weak references for cycle prevention
//!
//! ## Quick Start
//!
//! ```rust
//! use mission4::{SimpleLinkedList, RcLinkedList};
//!
//! // Box-based simple implementation
//! let mut simple_list = SimpleLinkedList::new();
//! simple_list.push_front(42);
//! simple_list.push_front(24);
//! assert_eq!(simple_list.pop_front(), Some(24));
//!
//! // Rc-based flexible implementation
//! let mut rc_list = RcLinkedList::new();
//! rc_list.push_front("Hello");
//! rc_list.push_front("World");
//! // Use try_peek_front for RcLinkedList
//! match rc_list.try_peek_front() {
//!     Ok(Some(value)) => assert_eq!(*value, "World"),
//!     _ => panic!("Expected value"),
//! };
//! ```
//!
//! ## Why Linked Lists are Challenging in Rust
//!
//! Linked lists demonstrate several core Rust concepts:
//!
//! 1. **Ownership Conflicts**: Traditional linked lists require aliasing
//! 2. **Interior Mutability**: Modifying through shared references
//! 3. **Reference Cycles**: Potential memory leaks in cyclic structures
//! 4. **Iterator Safety**: Preventing use-after-free in traversal
//!
//! ## Performance Characteristics
//!
//! | Operation | Box Implementation | Rc Implementation |
//! |-----------|-------------------|-------------------|
//! | `push_front` | O(1) | O(1) |
//! | `pop_front` | O(1) | O(1) |
//! | `peek_front` | O(1) | O(1) |
//! | Memory overhead | Minimal | Higher (ref counting) |
//!
//! ## Use Cases
//!
//! - **Educational**: Understanding Rust ownership patterns
//! - **Competitive Programming**: Custom data structures for specific algorithms
//! - **Graph Algorithms**: Node-based representations
//! - **Parser Implementation**: Recursive data structures

pub mod linked_list;

pub use linked_list::{
    IntoIter, Iter, IterMut, LinkedListError, RcLinkedList, RcNode, SimpleLinkedList,
};

#[cfg(test)]
mod tests {
    use super::*;

    #[test] // REQ-1: Basic linked list structure with owned pointers
    fn req1_box_based_ownership() {
        let mut list = SimpleLinkedList::new();

        // Test basic ownership transfer with Box
        let val = String::from("owned_data");
        list.push_front(val);
        // val is moved and cannot be used anymore

        assert_eq!(list.len(), 1);
        assert!(!list.is_empty());

        // Pop returns ownership
        let retrieved = list.pop_front().unwrap();
        assert_eq!(retrieved, "owned_data");
        assert!(list.is_empty());
    }

    #[test] // REQ-2: Interior mutability with Rc<RefCell<T>>
    fn req2_interior_mutability_patterns() {
        let mut list = RcLinkedList::new();

        // Test Rc<RefCell<T>> patterns
        list.push_front(42);
        list.push_front(24);

        // Try to get mutable reference through RefCell
        match list.try_peek_front_mut() {
            Ok(Some(mut val)) => {
                *val = 100; // Interior mutability in action
            }
            _ => panic!("Should be able to mutably borrow"),
        };

        // Verify the mutation worked
        match list.try_peek_front() {
            Ok(Some(val)) => assert_eq!(*val, 100),
            _ => panic!("Should be able to peek"),
        };
    }

    #[test] // REQ-3: Core list operations (push, pop, peek)
    fn req3_core_operations() {
        // Test SimpleLinkedList operations
        let mut simple = SimpleLinkedList::new();

        // Push operations
        simple.push_front(1);
        simple.push_front(2);
        simple.push_front(3);
        assert_eq!(simple.len(), 3);

        // Peek operations (immutable and mutable)
        assert_eq!(simple.peek_front(), Some(&3));
        if let Some(front) = simple.peek_front_mut() {
            *front = 30;
        }
        assert_eq!(simple.peek_front(), Some(&30));

        // Pop operations (LIFO order)
        assert_eq!(simple.pop_front(), Some(30));
        assert_eq!(simple.pop_front(), Some(2));
        assert_eq!(simple.pop_front(), Some(1));
        assert_eq!(simple.pop_front(), None);

        // Test RcLinkedList operations
        let mut rc_list = RcLinkedList::new();
        rc_list.push_front("first");
        rc_list.push_front("second");

        assert_eq!(rc_list.len(), 2);
        assert_eq!(rc_list.pop_front().unwrap(), Some("second"));
        assert_eq!(rc_list.pop_front().unwrap(), Some("first"));
    }

    #[test] // REQ-4: Safe iteration patterns
    fn req4_safe_iteration() {
        let mut list = SimpleLinkedList::new();
        list.push_front(1);
        list.push_front(2);
        list.push_front(3);

        // Test that we can safely iterate without use-after-free
        let current_val = list.peek_front().copied();
        let mut count = 0;

        while current_val.is_some() {
            count += 1;
            // In a real iterator, we'd advance to next
            // For now, just test that peeking is safe
            if count >= 10 {
                break;
            } // Safety check for infinite loop
        }

        // Verify list is still intact after peeking
        assert_eq!(list.len(), 3);
        assert_eq!(list.peek_front(), Some(&3));
    }

    #[test] // REQ-5: Memory management comparisons
    fn req5_memory_management_comparison() {
        // SimpleLinkedList: minimal overhead with Box
        let mut simple = SimpleLinkedList::new();
        simple.push_front(42);
        assert_eq!(simple.len(), 1);

        // RcLinkedList: higher overhead but shared ownership capability
        let mut rc_list = RcLinkedList::new();
        rc_list.push_front(42);

        // Get a reference to the head node to show shared ownership
        let head_ref = rc_list.get_head_ref();
        assert!(head_ref.is_some());

        // Both implementations should handle basic operations
        assert_eq!(simple.pop_front(), Some(42));

        // Need to drop the head reference before we can pop from rc_list
        drop(head_ref);
        assert_eq!(rc_list.pop_front().unwrap(), Some(42));
    }

    #[test] // REQ-6: Weak references for cycle prevention
    fn req6_weak_references() {
        let mut list = RcLinkedList::new();
        list.push_front("first");
        list.push_front("second");

        // Get head reference
        if let Some(head) = list.get_head_ref() {
            // The implementation uses weak references internally
            // to prevent cycles in the prev_weak field

            // Verify we can still manipulate the list
            let borrowed = head.borrow();
            assert_eq!(borrowed.data, "second");

            // The weak reference should not prevent cleanup
            drop(borrowed);
        }

        // List should still be functional
        assert_eq!(list.len(), 2);
        list.clear();
        assert!(list.is_empty());
    }
}

//! # Linked List Implementations
//!
//! This module contains the actual implementations of singly linked lists,
//! demonstrating different ownership patterns in Rust.

use std::cell::{Ref, RefCell, RefMut};
use std::fmt;
use std::rc::{Rc, Weak};

/// Simple linked list using Box for owned pointers
///
/// This implementation demonstrates the most straightforward approach to linked lists
/// in Rust, using `Box<T>` for heap allocation and owned pointers.
///
/// # Requirements Satisfied: REQ-1, REQ-3, REQ-5
///
/// # Examples
///
/// ```
/// use mission4::SimpleLinkedList;
///
/// let mut list = SimpleLinkedList::new();
/// list.push_front(1);
/// list.push_front(2);
/// assert_eq!(list.pop_front(), Some(2));
/// assert_eq!(list.len(), 1);
/// ```
#[derive(Debug)]
pub struct SimpleLinkedList<T> {
    head: Option<Box<Node<T>>>,
    length: usize,
}

/// Node for the simple linked list implementation
#[derive(Debug)]
struct Node<T> {
    data: T,
    next: Option<Box<Node<T>>>,
}

/// Linked list using `Rc<RefCell<T>>` for shared ownership and interior mutability
///
/// This implementation demonstrates advanced Rust patterns for scenarios requiring
/// shared ownership of nodes. Uses reference counting and interior mutability.
///
/// # Requirements Satisfied: REQ-2, REQ-3, REQ-5, REQ-6
///
/// # Examples
///
/// ```
/// use mission4::RcLinkedList;
///
/// let mut list = RcLinkedList::new();
/// list.push_front("hello");
/// list.push_front("world");
/// assert_eq!(list.len(), 2);
/// ```
#[derive(Debug)]
pub struct RcLinkedList<T> {
    head: Option<Rc<RefCell<RcNode<T>>>>,
    length: usize,
}

/// Node for the Rc-based linked list implementation
#[derive(Debug)]
pub struct RcNode<T> {
    pub data: T,
    pub next: Option<Rc<RefCell<RcNode<T>>>>,
    // For advanced patterns, we might add a weak back-reference
    pub prev_weak: Option<Weak<RefCell<RcNode<T>>>>,
}

/// Error types for linked list operations
#[derive(Debug, Clone, PartialEq)]
pub enum LinkedListError {
    /// Attempted to borrow a node that is already mutably borrowed
    BorrowError,
    /// Node still has multiple references and cannot be unwrapped
    MultipleReferences,
    /// Operation attempted on empty list
    EmptyList,
}

impl fmt::Display for LinkedListError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LinkedListError::BorrowError => write!(f, "Node is already mutably borrowed"),
            LinkedListError::MultipleReferences => write!(f, "Node still has multiple references"),
            LinkedListError::EmptyList => write!(f, "Operation attempted on empty list"),
        }
    }
}

impl std::error::Error for LinkedListError {}

// ============================================================================
// SimpleLinkedList Implementation
// ============================================================================

impl<T> SimpleLinkedList<T> {
    /// Creates a new empty linked list
    ///
    /// # Requirements Satisfied: REQ-1
    ///
    /// # Time Complexity: O(1)
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::SimpleLinkedList;
    ///
    /// let list: SimpleLinkedList<i32> = SimpleLinkedList::new();
    /// assert!(list.is_empty());
    /// ```
    pub fn new() -> Self {
        SimpleLinkedList {
            head: None,
            length: 0,
        }
    }

    /// Adds an element to the front of the list
    ///
    /// # Requirements Satisfied: REQ-3
    ///
    /// # Time Complexity: O(1)
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::SimpleLinkedList;
    ///
    /// let mut list = SimpleLinkedList::new();
    /// list.push_front(42);
    /// assert_eq!(list.len(), 1);
    /// assert_eq!(list.peek_front(), Some(&42));
    /// ```
    pub fn push_front(&mut self, value: T) {
        let new_node = Box::new(Node {
            data: value,
            next: self.head.take(),
        });
        self.head = Some(new_node);
        self.length += 1;
    }

    /// Removes and returns the front element
    ///
    /// # Requirements Satisfied: REQ-3
    ///
    /// # Time Complexity: O(1)
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::SimpleLinkedList;
    ///
    /// let mut list = SimpleLinkedList::new();
    /// list.push_front(42);
    /// assert_eq!(list.pop_front(), Some(42));
    /// assert!(list.is_empty());
    /// ```
    pub fn pop_front(&mut self) -> Option<T> {
        self.head.take().map(|old_head| {
            self.head = old_head.next;
            self.length -= 1;
            old_head.data
        })
    }

    /// Gets a reference to the front element without removing it
    ///
    /// # Requirements Satisfied: REQ-3
    ///
    /// # Time Complexity: O(1)
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::SimpleLinkedList;
    ///
    /// let mut list = SimpleLinkedList::new();
    /// list.push_front(42);
    /// assert_eq!(list.peek_front(), Some(&42));
    /// assert_eq!(list.len(), 1); // List unchanged
    /// ```
    pub fn peek_front(&self) -> Option<&T> {
        self.head.as_ref().map(|node| &node.data)
    }

    /// Gets a mutable reference to the front element
    ///
    /// # Requirements Satisfied: REQ-3
    ///
    /// # Time Complexity: O(1)
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::SimpleLinkedList;
    ///
    /// let mut list = SimpleLinkedList::new();
    /// list.push_front(42);
    /// if let Some(front) = list.peek_front_mut() {
    ///     *front = 100;
    /// }
    /// assert_eq!(list.peek_front(), Some(&100));
    /// ```
    pub fn peek_front_mut(&mut self) -> Option<&mut T> {
        self.head.as_mut().map(|node| &mut node.data)
    }

    /// Returns true if the list is empty
    ///
    /// # Requirements Satisfied: REQ-1, REQ-3
    ///
    /// # Time Complexity: O(1)
    pub fn is_empty(&self) -> bool {
        self.head.is_none()
    }

    /// Returns the number of elements in the list
    ///
    /// # Requirements Satisfied: REQ-1, REQ-3
    ///
    /// # Time Complexity: O(1)
    pub fn len(&self) -> usize {
        self.length
    }

    /// Clears all elements from the list
    ///
    /// # Requirements Satisfied: REQ-3
    ///
    /// # Time Complexity: O(n) where n is the number of elements
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::SimpleLinkedList;
    ///
    /// let mut list = SimpleLinkedList::new();
    /// list.push_front(1);
    /// list.push_front(2);
    /// list.clear();
    /// assert!(list.is_empty());
    /// assert_eq!(list.len(), 0);
    /// ```
    pub fn clear(&mut self) {
        while self.pop_front().is_some() {}
    }

    /// Returns an iterator over references to the elements
    ///
    /// # Requirements Satisfied: REQ-4
    ///
    /// # Time Complexity: O(1) to create, O(n) to consume
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::SimpleLinkedList;
    ///
    /// let mut list = SimpleLinkedList::new();
    /// list.push_front(1);
    /// list.push_front(2);
    ///
    /// let collected: Vec<&i32> = list.iter().collect();
    /// assert_eq!(collected, vec![&2, &1]);
    /// ```
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            current: self.head.as_deref(),
        }
    }

    /// Returns an iterator over mutable references to the elements
    ///
    /// # Requirements Satisfied: REQ-4
    ///
    /// # Time Complexity: O(1) to create, O(n) to consume
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::SimpleLinkedList;
    ///
    /// let mut list = SimpleLinkedList::new();
    /// list.push_front(1);
    /// list.push_front(2);
    ///
    /// for item in list.iter_mut() {
    ///     *item *= 2;
    /// }
    ///
    /// assert_eq!(list.pop_front(), Some(4));
    /// assert_eq!(list.pop_front(), Some(2));
    /// ```
    pub fn iter_mut(&mut self) -> IterMut<'_, T> {
        IterMut {
            current: self.head.as_deref_mut(),
        }
    }
}

impl<T> Default for SimpleLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

// ============================================================================
// Iterator Support for SimpleLinkedList
// ============================================================================

/// Iterator that yields values by consuming the list
pub struct IntoIter<T> {
    list: SimpleLinkedList<T>,
}

/// Iterator that yields references to values
pub struct Iter<'a, T> {
    current: Option<&'a Node<T>>,
}

/// Iterator that yields mutable references to values
pub struct IterMut<'a, T> {
    current: Option<&'a mut Node<T>>,
}

impl<T> Iterator for IntoIter<T> {
    type Item = T;

    fn next(&mut self) -> Option<Self::Item> {
        self.list.pop_front()
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let len = self.list.len();
        (len, Some(len))
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<Self::Item> {
        self.current.map(|node| {
            self.current = node.next.as_deref();
            &node.data
        })
    }
}

impl<'a, T> Iterator for IterMut<'a, T> {
    type Item = &'a mut T;

    fn next(&mut self) -> Option<Self::Item> {
        self.current.take().map(|node| {
            self.current = node.next.as_deref_mut();
            &mut node.data
        })
    }
}

impl<T> IntoIterator for SimpleLinkedList<T> {
    type Item = T;
    type IntoIter = IntoIter<T>;

    fn into_iter(self) -> Self::IntoIter {
        IntoIter { list: self }
    }
}

impl<'a, T> IntoIterator for &'a SimpleLinkedList<T> {
    type Item = &'a T;
    type IntoIter = Iter<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

// ============================================================================
// RcLinkedList Implementation
// ============================================================================

impl<T> RcLinkedList<T> {
    /// Creates a new empty linked list
    ///
    /// # Requirements Satisfied: REQ-2
    ///
    /// # Time Complexity: O(1)
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::RcLinkedList;
    ///
    /// let list: RcLinkedList<i32> = RcLinkedList::new();
    /// assert!(list.is_empty());
    /// ```
    pub fn new() -> Self {
        RcLinkedList {
            head: None,
            length: 0,
        }
    }

    /// Adds an element to the front of the list
    ///
    /// # Requirements Satisfied: REQ-2, REQ-3
    ///
    /// # Time Complexity: O(1)
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::RcLinkedList;
    ///
    /// let mut list = RcLinkedList::new();
    /// list.push_front(42);
    /// assert_eq!(list.len(), 1);
    /// ```
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(RcNode {
            data: value,
            next: self.head.take(),
            prev_weak: None,
        }));

        // Set up weak back-reference in the old head
        if let Some(ref old_head) = new_node.borrow().next {
            old_head.borrow_mut().prev_weak = Some(Rc::downgrade(&new_node));
        }

        self.head = Some(new_node);
        self.length += 1;
    }

    /// Removes and returns the front element
    ///
    /// # Requirements Satisfied: REQ-2, REQ-3
    ///
    /// # Time Complexity: O(1)
    ///
    /// Returns an error if the node cannot be unwrapped due to multiple references.
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::RcLinkedList;
    ///
    /// let mut list = RcLinkedList::new();
    /// list.push_front(42);
    /// assert_eq!(list.pop_front(), Ok(Some(42)));
    /// assert!(list.is_empty());
    /// ```
    pub fn pop_front(&mut self) -> Result<Option<T>, LinkedListError> {
        match self.head.take() {
            None => Ok(None),
            Some(old_head) => {
                match Rc::try_unwrap(old_head) {
                    Ok(cell) => {
                        let node = cell.into_inner();
                        self.head = node.next;
                        // Clear weak reference in new head if exists
                        if let Some(ref new_head) = self.head {
                            new_head.borrow_mut().prev_weak = None;
                        }
                        self.length -= 1;
                        Ok(Some(node.data))
                    }
                    Err(rc_node) => {
                        // Put the node back and return error
                        self.head = Some(rc_node);
                        Err(LinkedListError::MultipleReferences)
                    }
                }
            }
        }
    }

    /// Attempts to get a reference to the front element
    ///
    /// # Requirements Satisfied: REQ-2, REQ-3
    ///
    /// # Time Complexity: O(1)
    ///
    /// Note: This operation can fail if the front node is currently mutably borrowed.
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::RcLinkedList;
    ///
    /// let mut list = RcLinkedList::new();
    /// list.push_front(42);
    ///
    /// match list.try_peek_front() {
    ///     Ok(Some(value)) => println!("Front value: {}", *value),
    ///     Ok(None) => println!("List is empty"),
    ///     Err(_) => println!("Could not borrow front node"),
    /// };
    /// ```
    pub fn try_peek_front(&self) -> Result<Option<Ref<'_, T>>, LinkedListError> {
        match &self.head {
            None => Ok(None),
            Some(node) => match node.try_borrow() {
                Ok(borrowed) => Ok(Some(Ref::map(borrowed, |n| &n.data))),
                Err(_) => Err(LinkedListError::BorrowError),
            },
        }
    }

    /// Attempts to get a mutable reference to the front element
    ///
    /// # Requirements Satisfied: REQ-2, REQ-3
    ///
    /// # Time Complexity: O(1)
    ///
    /// Note: This operation can fail if the front node is currently borrowed.
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::RcLinkedList;
    ///
    /// let mut list = RcLinkedList::new();
    /// list.push_front(42);
    ///
    /// match list.try_peek_front_mut() {
    ///     Ok(Some(mut value)) => *value = 100,
    ///     Ok(None) => println!("List is empty"),
    ///     Err(_) => println!("Could not mutably borrow front node"),
    /// };
    /// ```
    pub fn try_peek_front_mut(&self) -> Result<Option<RefMut<'_, T>>, LinkedListError> {
        match &self.head {
            None => Ok(None),
            Some(node) => match node.try_borrow_mut() {
                Ok(borrowed) => Ok(Some(RefMut::map(borrowed, |n| &mut n.data))),
                Err(_) => Err(LinkedListError::BorrowError),
            },
        }
    }

    /// Returns true if the list is empty
    ///
    /// # Requirements Satisfied: REQ-2, REQ-3
    ///
    /// # Time Complexity: O(1)
    pub fn is_empty(&self) -> bool {
        self.head.is_none()
    }

    /// Returns the number of elements in the list
    ///
    /// # Requirements Satisfied: REQ-2, REQ-3
    ///
    /// # Time Complexity: O(1)
    pub fn len(&self) -> usize {
        self.length
    }

    /// Clears all elements from the list
    ///
    /// # Requirements Satisfied: REQ-2, REQ-3
    ///
    /// # Time Complexity: O(n) where n is the number of elements
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::RcLinkedList;
    ///
    /// let mut list = RcLinkedList::new();
    /// list.push_front(1);
    /// list.push_front(2);
    /// list.clear();
    /// assert!(list.is_empty());
    /// assert_eq!(list.len(), 0);
    /// ```
    pub fn clear(&mut self) {
        while let Ok(Some(_)) = self.pop_front() {}
    }

    /// Gets a cloned reference to the head node for advanced operations
    ///
    /// # Requirements Satisfied: REQ-6
    ///
    /// This allows for advanced patterns where you need direct access to the Rc.
    /// Be careful not to create reference cycles.
    ///
    /// # Examples
    ///
    /// ```
    /// use mission4::RcLinkedList;
    ///
    /// let mut list = RcLinkedList::new();
    /// list.push_front(42);
    ///
    /// if let Some(head_ref) = list.get_head_ref() {
    ///     // Can share this reference with other data structures
    ///     println!("Head ref count: {}", std::rc::Rc::strong_count(&head_ref));
    /// }
    /// ```
    pub fn get_head_ref(&self) -> Option<Rc<RefCell<RcNode<T>>>> {
        self.head.clone()
    }
}

impl<T> Default for RcLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

// ============================================================================
// Additional Trait Implementations for SimpleLinkedList
// ============================================================================

impl<T: std::fmt::Display> std::fmt::Display for SimpleLinkedList<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "[")?;
        let mut first = true;
        for item in self.iter() {
            if !first {
                write!(f, ", ")?;
            }
            write!(f, "{}", item)?;
            first = false;
        }
        write!(f, "]")
    }
}

impl<T: Clone> Clone for SimpleLinkedList<T> {
    fn clone(&self) -> Self {
        let mut new_list = SimpleLinkedList::new();
        let items: Vec<T> = self.iter().cloned().collect();

        // Reverse to maintain order when pushing to front
        for item in items.into_iter().rev() {
            new_list.push_front(item);
        }

        new_list
    }
}

impl<T: PartialEq> PartialEq for SimpleLinkedList<T> {
    fn eq(&self, other: &Self) -> bool {
        if self.len() != other.len() {
            return false;
        }

        self.iter().eq(other.iter())
    }
}

impl<T> std::iter::FromIterator<T> for SimpleLinkedList<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Self {
        let mut list = SimpleLinkedList::new();
        let items: Vec<T> = iter.into_iter().collect();

        // Reverse to maintain order when pushing to front
        for item in items.into_iter().rev() {
            list.push_front(item);
        }

        list
    }
}

impl<T> std::iter::Extend<T> for SimpleLinkedList<T> {
    fn extend<I: IntoIterator<Item = T>>(&mut self, iter: I) {
        // Add items to front, which means last item in iterator becomes first in list
        for item in iter {
            self.push_front(item);
        }
    }
}

//! Comprehensive unit tests for Mission 4: Singly Linked List
//!
//! This test suite covers all requirements (REQ-1 through REQ-6) with full traceability.

use mission4::{LinkedListError, RcLinkedList, SimpleLinkedList};

// ============================================================================
// REQ-1: Basic Linked List Structure Tests
// ============================================================================

#[test] // REQ-1
fn req1_simple_list_basic_structure() {
    let list: SimpleLinkedList<i32> = SimpleLinkedList::new();
    assert!(list.is_empty());
    assert_eq!(list.len(), 0);
}

#[test] // REQ-1
fn req1_simple_list_node_ownership() {
    let mut list = SimpleLinkedList::new();

    // Test that ownership transfer works correctly
    let value = String::from("test");
    list.push_front(value); // value is moved

    assert_eq!(list.len(), 1);
    assert_eq!(list.peek_front(), Some(&String::from("test")));
}

#[test] // REQ-1
fn req1_memory_safety_after_drop() {
    let mut list = SimpleLinkedList::new();
    list.push_front(1);
    list.push_front(2);
    list.push_front(3);

    // All memory should be cleaned up properly when list is dropped
    drop(list);
    // If we reach here without segfault, memory management is correct
}

// ============================================================================
// REQ-2: Interior Mutability with Rc<RefCell<T>> Tests
// ============================================================================

#[test] // REQ-2
fn req2_rc_list_basic_structure() {
    let list: RcLinkedList<i32> = RcLinkedList::new();
    assert!(list.is_empty());
    assert_eq!(list.len(), 0);
}

#[test] // REQ-2
fn req2_rc_list_shared_ownership() {
    let mut list = RcLinkedList::new();
    list.push_front(42);

    // Get a reference to the head node
    let head_ref = list.get_head_ref();
    assert!(head_ref.is_some());

    // Verify reference counting
    if let Some(head) = head_ref {
        assert!(std::rc::Rc::strong_count(&head) >= 1);
    }
}

#[test] // REQ-2
fn req2_interior_mutability_borrow_checking() {
    let mut list = RcLinkedList::new();
    list.push_front(100);

    // Test try_peek_front for runtime borrow checking
    match list.try_peek_front() {
        Ok(Some(value)) => assert_eq!(*value, 100),
        Ok(None) => panic!("Expected Some value"),
        Err(_) => panic!("Expected successful borrow"),
    };
}

#[test] // REQ-2
fn req2_weak_references_no_cycles() {
    let mut list = RcLinkedList::new();
    list.push_front(1);
    list.push_front(2);

    // The implementation uses weak references to prevent cycles
    // Verify list can be cleaned up properly
    let initial_len = list.len();
    list.clear();
    assert_eq!(list.len(), 0);
    assert!(initial_len > 0);
}

// ============================================================================
// REQ-3: Core List Operations Tests
// ============================================================================

#[test] // REQ-3
fn req3_simple_push_front_constant_time() {
    let mut list = SimpleLinkedList::new();

    // Multiple pushes should all be O(1)
    for i in 0..1000 {
        list.push_front(i);
        assert_eq!(list.len(), i + 1);
    }

    assert_eq!(list.peek_front(), Some(&999));
}

#[test] // REQ-3
fn req3_simple_pop_front_constant_time() {
    let mut list = SimpleLinkedList::new();

    // Setup
    for i in 0..100 {
        list.push_front(i);
    }

    // Pop should be O(1) and maintain LIFO order
    for i in (0..100).rev() {
        assert_eq!(list.pop_front(), Some(i));
    }

    assert!(list.is_empty());
    assert_eq!(list.pop_front(), None);
}

#[test] // REQ-3
fn req3_simple_peek_operations() {
    let mut list = SimpleLinkedList::new();

    // Peek on empty list
    assert_eq!(list.peek_front(), None);
    assert_eq!(list.peek_front_mut(), None);

    list.push_front(42);

    // Immutable peek
    assert_eq!(list.peek_front(), Some(&42));

    // Mutable peek and modification
    if let Some(front) = list.peek_front_mut() {
        *front = 100;
    }

    assert_eq!(list.peek_front(), Some(&100));
    assert_eq!(list.len(), 1); // Length unchanged
}

#[test] // REQ-3
fn req3_rc_list_operations() {
    let mut list = RcLinkedList::new();

    // Test all basic operations
    list.push_front(1);
    list.push_front(2);
    list.push_front(3);

    assert_eq!(list.len(), 3);
    assert!(!list.is_empty());

    // Pop operations
    assert_eq!(list.pop_front(), Ok(Some(3)));
    assert_eq!(list.pop_front(), Ok(Some(2)));
    assert_eq!(list.len(), 1);

    // Peek operations
    match list.try_peek_front() {
        Ok(Some(value)) => assert_eq!(*value, 1),
        _ => panic!("Expected value"),
    };
}

#[test] // REQ-3
fn req3_clear_operation() {
    let mut simple_list = SimpleLinkedList::new();
    let mut rc_list = RcLinkedList::new();

    // Populate both lists
    for i in 0..50 {
        simple_list.push_front(i);
        rc_list.push_front(i);
    }

    // Clear both
    simple_list.clear();
    rc_list.clear();

    assert!(simple_list.is_empty());
    assert!(rc_list.is_empty());
    assert_eq!(simple_list.len(), 0);
    assert_eq!(rc_list.len(), 0);
}

// ============================================================================
// REQ-4: Safe Iteration Patterns Tests
// ============================================================================

#[test] // REQ-4
fn req4_consuming_iterator() {
    let mut list = SimpleLinkedList::new();
    for i in 0..5 {
        list.push_front(i);
    }

    let collected: Vec<i32> = list.into_iter().collect();
    assert_eq!(collected, vec![4, 3, 2, 1, 0]);
}

#[test] // REQ-4
fn req4_borrowing_iterator() {
    let mut list = SimpleLinkedList::new();
    for i in 0..5 {
        list.push_front(i);
    }

    let collected: Vec<&i32> = list.iter().collect();
    assert_eq!(collected, vec![&4, &3, &2, &1, &0]);

    // List should still be usable
    assert_eq!(list.len(), 5);
}

#[test] // REQ-4
fn req4_mutable_iterator() {
    let mut list = SimpleLinkedList::new();
    for i in 0..5 {
        list.push_front(i);
    }

    // Modify all elements
    for item in list.iter_mut() {
        *item *= 2;
    }

    let collected: Vec<i32> = list.into_iter().collect();
    assert_eq!(collected, vec![8, 6, 4, 2, 0]);
}

#[test] // REQ-4
fn req4_iterator_traits() {
    let mut list = SimpleLinkedList::new();
    for i in 0..10 {
        list.push_front(i);
    }

    // Test size_hint
    let mut iter = list.into_iter();
    assert_eq!(iter.size_hint(), (10, Some(10)));

    iter.next();
    assert_eq!(iter.size_hint(), (9, Some(9)));
}

#[test] // REQ-4
fn req4_from_iterator() {
    let data = vec![1, 2, 3, 4, 5];
    let list: SimpleLinkedList<i32> = data.into_iter().collect();

    // Should maintain order
    let collected: Vec<i32> = list.into_iter().collect();
