        assert_eq!(counter.get(&"banana"), 1);
        assert_eq!(counter.get(&"missing"), 0);
        assert_eq!(counter.total_count(), 3);
        assert_eq!(counter.unique_count(), 2);
    }

    #[test]
    fn test_increment_by() {
