            "b".to_string(),
            "a".to_string(),
            "c".to_string(),
            "a".to_string(),
        ];
        counter.count_multiple(items);

        assert_eq!(counter.get(&"a".to_string()), 3);
        assert_eq!(counter.get(&"b".to_string()), 1);
        assert_eq!(counter.get(&"c".to_string()), 1);
        assert_eq!(counter.total_count(), 5);
    }

    #[test]
