    let max_x = visited.iter().map(|c| c.x).max().unwrap();
    let min_y = visited.iter().map(|c| c.y).min().unwrap();
    let max_y = visited.iter().map(|c| c.y).max().unwrap();

    println!(
        "Santa moved within bounds: x=[{}, {}], y=[{}, {}]",
        min_x, max_x, min_y, max_y
