        );
    }

    #[test]
    fn test_movement_bounds() {
        let coord = Coord::new(2, 3);

        // These should work
        assert!(coord.try_move_in_direction(Direction::North, 3).is_some());
        assert!(coord.try_move_in_direction(Direction::West, 2).is_some());

        // These should fail (underflow)
        assert!(coord.try_move_in_direction(Direction::North, 4).is_none());
        assert!(coord.try_move_in_direction(Direction::West, 3).is_none());
    }

    #[test]
    fn test_distances() {
        let a = Coord::new(1, 1);
        let b = Coord::new(4, 5);

        assert_eq!(a.manhattan_distance(b), 7); // |4-1| + |5-1| = 3 + 4 = 7
        assert_eq!(a.chebyshev_distance(b), 4); // max(3, 4) = 4
        assert_eq!(a.euclidean_distance_squared(b), 25); // 3² + 4² = 9 + 16 = 25
    }

    #[test]
    fn test_neighbors() {
        let center = Coord::new(5, 5);

        let neighbors4: Vec<_> = center.neighbors_4().collect();
        assert!(neighbors4.contains(&Coord::new(5, 4))); // North
        assert!(neighbors4.contains(&Coord::new(5, 6))); // South
        assert!(neighbors4.contains(&Coord::new(6, 5))); // East
        assert!(neighbors4.contains(&Coord::new(4, 5))); // West

        let neighbors8: Vec<_> = center.neighbors_8().collect();
        assert!(neighbors8.len() == 8);
        assert!(neighbors8.contains(&Coord::new(4, 4))); // NorthWest
        assert!(neighbors8.contains(&Coord::new(6, 6))); // SouthEast
    }

    #[test]
    fn test_neighbors_boundary() {
        let corner = Coord::new(0, 0);

        // At corner, some neighbors will be invalid due to underflow
        let neighbors4: Vec<_> = corner.neighbors_4().collect();
        assert!(neighbors4.len() < 4);
        assert!(neighbors4.contains(&Coord::new(1, 0))); // East
        assert!(neighbors4.contains(&Coord::new(0, 1))); // South
    }

    #[test]
    fn test_arithmetic() {
        let a = Coord::new(3, 4);
        let b = Coord::new(1, 2);

        assert_eq!(a + b, Coord::new(4, 6));
        assert_eq!(a - b, Coord::new(2, 2));

        let mut c = a;
        c += b;
        assert_eq!(c, Coord::new(4, 6));
    }

    #[test]
    fn test_hash_map_compatibility() {
        let mut map: HashMap<Coord, String> = HashMap::new();

        let coord1 = Coord::new(5, 10);
        let coord2 = Coord::new(5, 10); // Same coordinates

        map.insert(coord1, "first".to_string());
        assert_eq!(map.get(&coord2), Some(&"first".to_string()));
    }

    #[test]
    fn test_conversions() {
        let coord = Coord::new(3, 7);
        let tuple: (usize, usize) = coord.into();
        assert_eq!(tuple, (3, 7));

        let coord2: Coord = (5, 2).into();
        assert_eq!(coord2, Coord::new(5, 2));

        let (sx, sy) = coord.to_signed();
        assert_eq!((sx, sy), (3, 7));

        let coord3 = Coord::from_signed(sx, sy).unwrap();
        assert_eq!(coord3, coord);
    }
}

//! Direction enumeration for 2D navigation
//!
//! Provides the Direction enum for representing movement directions
//! with rotation operations and vector calculations.

use std::fmt;

/// Cardinal and diagonal directions for 2D navigation
///
/// Uses standard compass directions with the following coordinate system:
/// - North: decreases y (up on screen/grid)
/// - South: increases y (down on screen/grid)  
/// - East: increases x (right)
/// - West: decreases x (left)
#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash)]
pub enum Direction {
    North,
    NorthEast,
    East,
    SouthEast,
    South,
    SouthWest,
    West,
    NorthWest,
}

impl Direction {
    /// Get all 4 cardinal directions (North, South, East, West)
    pub fn cardinals() -> [Direction; 4] {
        [
            Direction::North,
            Direction::South,
            Direction::East,
            Direction::West,
        ]
    }

    /// Get all 8 directions (cardinals + diagonals)
    pub fn all() -> [Direction; 8] {
        [
            Direction::North,
            Direction::NorthEast,
            Direction::East,
            Direction::SouthEast,
            Direction::South,
            Direction::SouthWest,
            Direction::West,
            Direction::NorthWest,
        ]
    }

    /// Check if this is a cardinal direction (not diagonal)
    pub fn is_cardinal(self) -> bool {
        matches!(
            self,
            Direction::North | Direction::South | Direction::East | Direction::West
        )
    }

    /// Check if this is a diagonal direction
    pub fn is_diagonal(self) -> bool {
        !self.is_cardinal()
    }

    /// Get the opposite direction
    pub fn opposite(self) -> Direction {
        match self {
            Direction::North => Direction::South,
            Direction::NorthEast => Direction::SouthWest,
            Direction::East => Direction::West,
            Direction::SouthEast => Direction::NorthWest,
            Direction::South => Direction::North,
            Direction::SouthWest => Direction::NorthEast,
            Direction::West => Direction::East,
            Direction::NorthWest => Direction::SouthEast,
        }
    }

    /// Rotate clockwise by 45 degrees
    pub fn rotate_clockwise(self) -> Direction {
        match self {
            Direction::North => Direction::NorthEast,
            Direction::NorthEast => Direction::East,
            Direction::East => Direction::SouthEast,
            Direction::SouthEast => Direction::South,
            Direction::South => Direction::SouthWest,
            Direction::SouthWest => Direction::West,
            Direction::West => Direction::NorthWest,
            Direction::NorthWest => Direction::North,
        }
    }

    /// Rotate counterclockwise by 45 degrees
    pub fn rotate_counterclockwise(self) -> Direction {
        match self {
            Direction::North => Direction::NorthWest,
            Direction::NorthWest => Direction::West,
            Direction::West => Direction::SouthWest,
            Direction::SouthWest => Direction::South,
            Direction::South => Direction::SouthEast,
            Direction::SouthEast => Direction::East,
            Direction::East => Direction::NorthEast,
            Direction::NorthEast => Direction::North,
        }
    }

    /// Rotate clockwise by 90 degrees (for cardinal directions)
    pub fn rotate_90_clockwise(self) -> Direction {
        match self {
            Direction::North => Direction::East,
            Direction::East => Direction::South,
            Direction::South => Direction::West,
            Direction::West => Direction::North,
            // For diagonal directions, rotate by 90 degrees
            Direction::NorthEast => Direction::SouthEast,
            Direction::SouthEast => Direction::SouthWest,
            Direction::SouthWest => Direction::NorthWest,
            Direction::NorthWest => Direction::NorthEast,
        }
    }

    /// Rotate counterclockwise by 90 degrees (for cardinal directions)
    pub fn rotate_90_counterclockwise(self) -> Direction {
        match self {
            Direction::North => Direction::West,
            Direction::West => Direction::South,
            Direction::South => Direction::East,
            Direction::East => Direction::North,
            // For diagonal directions, rotate by 90 degrees
            Direction::NorthEast => Direction::NorthWest,
            Direction::NorthWest => Direction::SouthWest,
            Direction::SouthWest => Direction::SouthEast,
            Direction::SouthEast => Direction::NorthEast,
        }
    }

    /// Get the unit vector (dx, dy) for this direction
    /// Returns (x_delta, y_delta) where positive x is East, positive y is South
    pub fn delta(self) -> (isize, isize) {
        match self {
            Direction::North => (0, -1),
            Direction::NorthEast => (1, -1),
            Direction::East => (1, 0),
            Direction::SouthEast => (1, 1),
            Direction::South => (0, 1),
            Direction::SouthWest => (-1, 1),
            Direction::West => (-1, 0),
            Direction::NorthWest => (-1, -1),
        }
    }

    /// Convert from a unit vector to direction
    /// Returns None if the vector doesn't correspond to a valid direction
    pub fn from_delta(dx: isize, dy: isize) -> Option<Direction> {
        match (dx.signum(), dy.signum()) {
            (0, -1) => Some(Direction::North),
            (1, -1) => Some(Direction::NorthEast),
            (1, 0) => Some(Direction::East),
            (1, 1) => Some(Direction::SouthEast),
            (0, 1) => Some(Direction::South),
            (-1, 1) => Some(Direction::SouthWest),
            (-1, 0) => Some(Direction::West),
            (-1, -1) => Some(Direction::NorthWest),
            _ => None,
        }
    }

    /// Get the direction from one coordinate to another
    /// Returns the primary direction (may not be exact for non-aligned coordinates)
    pub fn from_coords(
        from_x: usize,
        from_y: usize,
        to_x: usize,
        to_y: usize,
    ) -> Option<Direction> {
        let dx = to_x as isize - from_x as isize;
        let dy = to_y as isize - from_y as isize;

        if dx == 0 && dy == 0 {
            return None; // Same coordinate
        }

        Direction::from_delta(dx.signum(), dy.signum())
    }

    /// Get the angle in degrees (0 = North, clockwise)
    pub fn angle_degrees(self) -> f64 {
        match self {
            Direction::North => 0.0,
            Direction::NorthEast => 45.0,
            Direction::East => 90.0,
            Direction::SouthEast => 135.0,
            Direction::South => 180.0,
            Direction::SouthWest => 225.0,
            Direction::West => 270.0,
            Direction::NorthWest => 315.0,
        }
    }

    /// Create direction from angle in degrees (0 = North, clockwise)
    /// Rounds to the nearest 45-degree direction
    pub fn from_angle_degrees(degrees: f64) -> Direction {
        let normalized = ((degrees % 360.0) + 360.0) % 360.0; // Normalize to [0, 360)
        let octant = ((normalized + 22.5) / 45.0) as usize % 8;

        match octant {
            0 => Direction::North,
            1 => Direction::NorthEast,
            2 => Direction::East,
            3 => Direction::SouthEast,
            4 => Direction::South,
            5 => Direction::SouthWest,
            6 => Direction::West,
            7 => Direction::NorthWest,
            _ => unreachable!(),
        }
    }

    /// Get a single-character representation
    pub fn to_char(self) -> char {
        match self {
            Direction::North => '^',
            Direction::NorthEast => '╱',
            Direction::East => '>',
            Direction::SouthEast => '╲',
            Direction::South => 'v',
            Direction::SouthWest => '╱',
            Direction::West => '<',
            Direction::NorthWest => '╲',
        }
    }

    /// Parse from a character
    pub fn from_char(c: char) -> Option<Direction> {
        match c {
            '^' | 'N' | 'n' => Some(Direction::North),
            '>' | 'E' | 'e' => Some(Direction::East),
            'v' | 'S' | 's' => Some(Direction::South),
            '<' | 'W' | 'w' => Some(Direction::West),
            _ => None,
        }
    }
}

use std::str::FromStr;

impl FromStr for Direction {
    type Err = ();

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "north" | "n" | "up" | "u" => Ok(Direction::North),
            "northeast" | "ne" => Ok(Direction::NorthEast),
            "east" | "e" | "right" | "r" => Ok(Direction::East),
            "southeast" | "se" => Ok(Direction::SouthEast),
            "south" | "s" | "down" | "d" => Ok(Direction::South),
            "southwest" | "sw" => Ok(Direction::SouthWest),
            "west" | "w" | "left" | "l" => Ok(Direction::West),
            "northwest" | "nw" => Ok(Direction::NorthWest),
            _ => Err(()),
        }
    }
}

impl fmt::Display for Direction {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let name = match self {
            Direction::North => "North",
            Direction::NorthEast => "NorthEast",
            Direction::East => "East",
            Direction::SouthEast => "SouthEast",
            Direction::South => "South",
            Direction::SouthWest => "SouthWest",
            Direction::West => "West",
            Direction::NorthWest => "NorthWest",
        };
        write!(f, "{}", name)
    }
}

