// Memory Address Analysis in Rust
// Demonstrates when and how to print memory addresses like C pointers

#[derive(Debug)]
struct HashMapBucket<T> {
    data: Vec<T>,
    capacity: usize,
}

impl<T> HashMapBucket<T> {
    fn new() -> Self {
        Self {
            data: Vec::new(),
            capacity: 0,
        }
    }

    fn with_capacity(cap: usize) -> Self {
        Self {
            data: Vec::with_capacity(cap),
            capacity: cap,
        }
    }
}

fn main() {
    println!("=== Memory Address Analysis in Rust ===\n");

    // =======================================================================
    // 1. BASIC ADDRESS PRINTING (equivalent to C's &variable and printf("%p"))
    // =======================================================================
    println!("1. Basic Address Printing:");

    let x = 42i32;
    let y = 100i32;

    println!("   x = {} at address {:p}", x, &x);
    println!("   y = {} at address {:p}", y, &y);
    println!(
        "   Address difference: {} bytes",
        (&y as *const i32 as usize) - (&x as *const i32 as usize)
    );

    // =======================================================================
    // 2. STACK vs HEAP ALLOCATION VISUALIZATION
    // =======================================================================
    println!("\n2. Stack vs Heap Allocation:");

    let stack_array = [1, 2, 3, 4, 5];
    let heap_vec = vec![1, 2, 3, 4, 5];

    println!("   Stack array at: {:p}", &stack_array);
    println!("   Stack array[0] at: {:p}", &stack_array[0]);

    println!("   Vec struct at: {:p}", &heap_vec);
    println!("   Vec data pointer: {:p}", heap_vec.as_ptr());
    println!("   Vec[0] (on heap) at: {:p}", &heap_vec[0]);

    // Calculate distance from stack to heap
    let stack_addr = &stack_array as *const _ as usize;
    let heap_addr = heap_vec.as_ptr() as usize;
    println!(
        "   Stack-to-heap distance: {} bytes",
        if heap_addr > stack_addr {
            heap_addr - stack_addr
        } else {
            stack_addr - heap_addr
        }
    );

    // =======================================================================
    // 3. OWNERSHIP & BORROWING DEBUGGING
    // =======================================================================
    println!("\n3. Ownership & Borrowing Analysis:");

    let owner = String::from("Hello, Rust!");
    println!("   Owner string at: {:p}", &owner);
    println!("   String data at: {:p}", owner.as_ptr());

    let borrower = &owner;
    println!("   Borrower reference at: {:p}", &borrower);
    println!("   Borrower points to: {:p}", borrower.as_ptr());

    // Multiple references to same data
    let ref1 = &owner;
    let ref2 = &owner;
    println!("   ref1 at {:p}, points to {:p}", &ref1, ref1.as_ptr());
    println!("   ref2 at {:p}, points to {:p}", &ref2, ref2.as_ptr());
    println!(
        "   Same data? {}",
        std::ptr::eq(ref1.as_ptr(), ref2.as_ptr())
    );

    // =======================================================================
    // 4. DATA STRUCTURE INTERNAL LAYOUT (Mission5 HashMap style)
    // =======================================================================
    println!("\n4. Data Structure Layout Analysis:");

    let bucket1 = HashMapBucket::<i32>::new();
    let bucket2 = HashMapBucket::<i32>::with_capacity(10);

    println!("   bucket1 struct at: {:p}", &bucket1);
    println!("   bucket1.data Vec at: {:p}", &bucket1.data);
    println!("   bucket1.capacity at: {:p}", &bucket1.capacity);

    println!("   bucket2 struct at: {:p}", &bucket2);
    println!("   bucket2.data Vec at: {:p}", &bucket2.data);
    println!("   bucket2 allocated buffer: {:p}", bucket2.data.as_ptr());

    // =======================================================================
    // 5. PERFORMANCE ANALYSIS - CACHE LOCALITY
    // =======================================================================
    println!("\n5. Cache Locality Analysis:");

    // Contiguous array (cache-friendly)
    let contiguous = [0u32; 8];
    println!("   Contiguous array:");
    for (i, item) in contiguous.iter().enumerate() {
        println!(
            "     [{}] at {:p} (offset: {})",
            i,
            item,
            (item as *const u32 as usize) - (&contiguous[0] as *const u32 as usize)
        );
    }

    // Scattered pointers (cache-unfriendly)
    let scattered: Vec<Box<u32>> = (0..4).map(|i| Box::new(i * 10)).collect();
    println!("   Scattered Box allocations:");
    for (i, boxed) in scattered.iter().enumerate() {
        println!("     Box[{}] content at {:p}", i, boxed.as_ref());
    }

    // =======================================================================
    // 6. UNSAFE POINTER OPERATIONS (Advanced - use with caution!)
    // =======================================================================
    println!("\n6. Unsafe Pointer Operations:");

    let mut value = 100i32;
    let ptr = &mut value as *mut i32;

    println!("   Raw pointer: {:p}", ptr);

    unsafe {
        println!("   Dereferenced value: {}", *ptr);
        *ptr = 200; // Modify through raw pointer
        println!("   After modification: {}", *ptr);
    }
    println!("   Original variable: {}", value); // Shows the change

    // =======================================================================
    // 7. REAL-WORLD USE CASES
    // =======================================================================
    println!("\n7. Real-World Applications:");

    // A. Debugging memory leaks
    let large_vec: Vec<u32> = (0..1000).collect();
    println!(
        "   Large allocation at: {:p} (size: {} bytes)",
        large_vec.as_ptr(),
        large_vec.len() * std::mem::size_of::<u32>()
    );

    // B. Verifying data structure integrity
    let original_data = vec![1, 2, 3];
    let cloned_data = original_data.clone();
    println!("   Original data: {:p}", original_data.as_ptr());
    println!("   Cloned data: {:p}", cloned_data.as_ptr());
    println!(
        "   Independent copies? {}",
        !std::ptr::eq(original_data.as_ptr(), cloned_data.as_ptr())
    );

    // C. Performance profiling memory access patterns
    println!("\n   Memory layout summary:");
    println!("   - Stack variables are typically close together");
    println!("   - Heap allocations can be anywhere in memory");
    println!("   - Cache performance depends on access patterns");
    println!("   - Use addresses to verify optimization assumptions");

    println!("\n🎓 When to use address printing:");
    println!("   ✅ Debugging ownership and borrowing issues");
    println!("   ✅ Performance analysis and cache optimization");
    println!("   ✅ Verifying data structure layout and integrity");
    println!("   ✅ Understanding memory allocation patterns");
    println!("   ✅ Educational purposes (learning how Rust works)");
    println!("   ❌ Production logging (addresses change between runs)");
    println!("   ❌ Serialization or persistence (addresses are temporary)");
}

// Virtual Memory Address Space Analysis
// Explains why stack and heap can be "trillions" of bytes apart

fn main() {
    println!("=== Virtual Memory Address Space Analysis ===\n");

    // Let's examine those "impossible" addresses more carefully
    let stack_var = 42i32;
    let heap_vec = vec![1, 2, 3, 4, 5];

    let stack_addr = &stack_var as *const i32 as usize;
    let heap_addr = heap_vec.as_ptr() as usize;

    println!("🔍 Raw Address Analysis:");
    println!("   Stack address: 0x{:x} ({})", stack_addr, stack_addr);
    println!("   Heap address:  0x{:x} ({})", heap_addr, heap_addr);

    let distance = if heap_addr > stack_addr {
        heap_addr - stack_addr
    } else {
        stack_addr - heap_addr
    };

    println!("   Distance: {} bytes", distance);
    println!("   That's {:.2} GB", distance as f64 / 1_073_741_824.0);
    println!("   That's {:.2} TB", distance as f64 / 1_099_511_627_776.0);

    // =======================================================================
    // THE TRUTH: VIRTUAL MEMORY EXPLANATION
    // =======================================================================
    println!("\n💡 Why This Makes Sense - Virtual Memory:");

    println!("\n1. 64-bit Address Space:");
    println!("   - Total addressable space: 2^64 = 18 exabytes");
    println!("   - Most of it is VIRTUAL (not real RAM)");
    println!("   - OS spreads different regions far apart for security");

    println!("\n2. Typical 64-bit Memory Layout (Linux/Windows):");
    println!("   0x0000000000000000 - 0x00007fffffffffff : User space (128 TB)");
    println!("   0x0000000000000000 - 0x0000000000400000 : Program code");
    println!("   0x00007fff00000000 - 0x00007fffffffffff : Stack (grows down)");
    println!("   0x0000000100000000 - 0x00007f0000000000 : Heap (grows up)");
    println!("   0xffff800000000000 - 0xffffffffffffffff : Kernel space");

    println!("\n3. Address Space Layout Randomization (ASLR):");
    println!("   - Security feature that randomizes memory locations");
    println!("   - Stack might start at 0x7fff12345000");
    println!("   - Heap might start at 0x000012ab34000000");
    println!("   - Separation prevents buffer overflow attacks");

    // =======================================================================
    // DEMONSTRATION: MULTIPLE RUNS SHOW DIFFERENT ADDRESSES
    // =======================================================================
    println!("\n🔄 Run this program multiple times - addresses will change!");
    println!("   This proves ASLR (Address Space Layout Randomization) is working");

    // Let's examine the bit patterns
    println!("\n🔢 Bit Pattern Analysis:");
    println!("   Stack addr binary: {:064b}", stack_addr);
    println!("   Heap addr binary:  {:064b}", heap_addr);

    // Count leading zeros to see which part of 64-bit space we're using
    let stack_leading_zeros = stack_addr.leading_zeros();
    let heap_leading_zeros = heap_addr.leading_zeros();

    println!("   Stack using {} of 64 bits", 64 - stack_leading_zeros);
    println!("   Heap using {} of 64 bits", 64 - heap_leading_zeros);

    // =======================================================================
    // PHYSICAL vs VIRTUAL MEMORY
    // =======================================================================
    println!("\n🏭 Physical vs Virtual Reality:");

    println!("   Your computer probably has 8-32 GB RAM");
    println!("   But each process gets a 128 TB virtual address space!");
    println!("   The OS + MMU (Memory Management Unit) maps virtual → physical");

    println!("\n   Example mapping:");
    println!("   Virtual 0x00007fff12345678 → Physical 0x00000000abc12340");
    println!("   Virtual 0x000012ab34567890 → Physical 0x00000000def56780");

    println!("   The 'distance' in virtual space means nothing for physical layout!");

    // =======================================================================
    // PRACTICAL IMPLICATIONS
    // =======================================================================
    println!("\n⚡ Performance Implications:");

    // Show that virtual distance doesn't matter for cache performance
    let array1 = [1u32, 2, 3, 4, 5];
    let array2 = [10u32, 20, 30, 40, 50];

    println!("   Array 1 at: {:p}", &array1);
    println!("   Array 2 at: {:p}", &array2);

    let virtual_distance = (&array2 as *const _ as usize) - (&array1 as *const _ as usize);
    println!("   Virtual distance: {} bytes", virtual_distance);
    println!("   But they're probably adjacent in physical RAM!");
    println!("   Cache performance depends on PHYSICAL proximity, not virtual");

    // =======================================================================
    // DEBUGGING TIPS
    // =======================================================================
    println!("\n🛠️ Debugging Tips:");
    println!("   ✅ Compare addresses within the same allocation");
    println!("   ✅ Use addresses to verify data structure layout");
    println!("   ✅ Check for memory leaks by tracking allocation addresses");
    println!("   ❌ Don't worry about huge virtual address gaps");
    println!("   ❌ Virtual distance != physical distance");

    // Show meaningful address comparison
    println!("\n📏 Meaningful Address Comparisons:");
    let struct_data = (100u32, 200u32, 300u32);
    println!("   Tuple at: {:p}", &struct_data);
    println!("   Field 0: {:p} (offset 0)", &struct_data.0);
    println!(
        "   Field 1: {:p} (offset {})",
        &struct_data.1,
        (&struct_data.1 as *const u32 as usize) - (&struct_data.0 as *const u32 as usize)
    );
    println!(
        "   Field 2: {:p} (offset {})",
        &struct_data.2,
        (&struct_data.2 as *const u32 as usize) - (&struct_data.0 as *const u32 as usize)
    );

    println!("\n🎓 Key Takeaway:");
    println!("   Those 'TB distances' are virtual memory layout, not physical RAM!");
    println!("   Modern OS design puts stack and heap far apart for security.");
    println!("   Your 16GB laptop isn't secretly hiding 2TB of RAM! 😄");
}

// Chapter 5.3 - Method Syntax
// Demonstrates method syntax patterns used in Mission5 HashMap implementation

#[derive(Debug, Clone)]
struct Rectangle {
    width: u32,
    height: u32,
}

impl Rectangle {
    // Associated function constructors (Mission5 pattern: HashMap::new())
    fn new(width: u32, height: u32) -> Self {
        Self { width, height }
    }

    // Method - takes &self as first parameter (Mission5: map.get(&key))
    fn area(&self) -> u32 {
        self.width * self.height
    }

    // Method that takes another Rectangle as parameter
    fn can_hold(&self, other: &Rectangle) -> bool {
        self.width > other.width && self.height > other.height
    }

    // Associated function (Mission5 pattern: HashMap::with_capacity())
    fn square(size: u32) -> Self {
        Self::new(size, size) // Delegate to constructor
    }

    // Mutable method (Mission5 pattern: map.insert())
    fn scale(&mut self, factor: u32) {
        self.width *= factor;
        self.height *= factor;
    }

    fn width(&self) -> bool {
        self.width > 0
    }
}

fn main() {
    println!("Chapter 5.3 - Method Syntax & Memory Address Analysis");

    // =============================================================================
    // MEMORY ADDRESS PRINTING IN RUST (like C's pointer printing)
    // =============================================================================

    println!("\n🔍 Memory Address Analysis:");

    let rect1 = Rectangle {
        width: 30,
        height: 50,
    };

    // Print address of the struct itself
    println!("   rect1 address: {:p}", &rect1);

    // Print addresses of individual fields
    println!("   rect1.width address: {:p}", &rect1.width);
    println!("   rect1.height address: {:p}", &rect1.height);

    // Stack vs Heap demonstration
    let stack_rect = Rectangle::new(10, 20);
    let heap_rect = Box::new(Rectangle::new(10, 20));

    println!("\n📚 Stack vs Heap Addresses:");
    println!("   Stack rect: {:p}", &stack_rect);
    println!("   Heap rect (Box): {:p}", heap_rect.as_ref());
    println!("   Box itself: {:p}", &heap_rect);

    // Address changes with moves
    println!("\n🚚 Move Semantics & Address Changes:");
    let original = Rectangle::new(5, 5);
    println!("   Original address: {:p}", &original);

    let moved = original; // Move occurs here
    println!("   After move: {:p}", &moved);
    // Note: original is no longer accessible

    // Reference addresses vs value addresses
    println!("\n🔗 Reference vs Value Addresses:");
    let value = 42u32;
    let reference = &value;
    let reference_to_reference = &reference;

    println!("   Value address: {:p}", &value);
    println!("   Reference points to: {:p}", reference);
    println!("   Reference itself at: {:p}", &reference);
    println!("   Ref-to-ref points to: {:p}", reference_to_reference);
    println!("   Ref-to-ref itself at: {:p}", &reference_to_reference);

    // Using method syntax
    println!(
        "The area of the rectangle is {} square pixels.",
        rect1.area()
    );

    if rect1.width() {
        println!("The rectangle has a nonzero width; it is {}", rect1.width);
    } else {
        println!(
            "The rectangle does not have a nonzero width; it is {}",
            rect1.width
        );
    }

    // Multiple rectangles for can_hold example
    let rect2 = Rectangle {
        width: 10,
        height: 40,
    };
    let rect3 = Rectangle {
        width: 60,
        height: 45,
    };

    println!("Can rect1 hold rect2? {}", rect1.can_hold(&rect2));
    println!("Can rect1 hold rect3? {}", rect1.can_hold(&rect3));

    // Using associated function (Mission5: HashMap::new() pattern)
    let sq = Rectangle::square(3);
    println!("Created square: {:?}", sq);
    println!("Square area: {}", sq.area());

    // Demonstrate mutable methods (Mission5: map.insert() pattern)
    let mut scalable_rect = Rectangle::new(10, 15);
    println!("Before scaling: {:?}", scalable_rect);
    scalable_rect.scale(2);
    println!("After scaling by 2: {:?}", scalable_rect);

    // Demonstrate multiple impl blocks
    let rect4 = Rectangle::new(20, 30);
    println!("Rectangle perimeter: {}", rect4.perimeter());
}

// Multiple impl blocks are allowed
impl Rectangle {
    fn perimeter(&self) -> u32 {
        2 * (self.width + self.height)
    }
}

// Chapter 5.2 - An Example Program Using Structs
// Rectangle area calculation program

// Chapter 5.2 of The Rust Programming Language (“An Example Program Using Structs”) walks through building a small program to demonstrate how structs can organize related data and methods in Rust. Here’s a concise summary:
// Goal of the Example
// Build a program that calculates the area of a rectangle using structs instead of separate variables.
// Key Steps and Concepts
// Starting with Separate Variables
// Initially, the area is calculated using two separate variables (width and height).
// This approach works but doesn’t group related data together.
// Using Tuples
// Next, the example uses a tuple (width, height) to pass dimensions to a function.
// Tuples group values but lack clarity because the fields have no names.
// Introducing Structs
// Define a Rectangle struct with named fields:
// Ruststruct Rectangle {    width: u32,    height: u32,}Show more lines
// This improves readability and makes the code self-documenting.
// Implementing Methods
// Use impl to define methods for the struct:
// Rustimpl Rectangle {    fn area(&self) -> u32 {        self.width * self.height    }}Show more lines
// &self is a shorthand for borrowing the instance immutably.
// Adding More Functionality
// Additional methods like can_hold(&self, other: &Rectangle) demonstrate how structs can encapsulate logic related to their data.
// Using dbg! and #[derive(Debug)]
// The dbg! macro and Debug trait help print struct values for debugging.
// Takeaways
// Structs provide clarity, organization, and encapsulation.
// Methods in impl blocks allow behavior to be associated with data.
// Rust encourages ownership and borrowing principles even in method definitions.

#[derive(Debug)]
struct Rectangle {
    width: u32,
    height: u32,
}

fn main() {
    println!("Chapter 5.2 - An Example Program Using Structs");

    // Version 1: Using separate variables
    let width1 = 30;
    let height1 = 50;
    println!(
        "The area of the rectangle is {} square pixels.",
        area_separate(width1, height1)
    );

    // Version 2: Using tuples
    let rect1 = (30, 50);
    println!(
        "The area of the rectangle is {} square pixels.",
        area_tuple(rect1)
    );

    // Version 3: Using structs
    let rect2 = Rectangle {
        width: 30,
        height: 50,
    };
    println!(
        "The area of the rectangle is {} square pixels.",
        area_struct(&rect2)
    );

    // Debug printing
    println!("rect2 is {:?}", rect2);
    println!("rect2 is {:#?}", rect2);

    // Using dbg! macro
    let scale = 2;
    let rect3 = Rectangle {
        width: dbg!(30 * scale),
        height: 50,
    };
    dbg!(&rect3); // reference passed to dbg! so it doesn't take ownership
}

fn area_separate(width: u32, height: u32) -> u32 {
    width * height
}

fn area_tuple(dimensions: (u32, u32)) -> u32 {
    dimensions.0 * dimensions.1
}

fn area_struct(rectangle: &Rectangle) -> u32 {
    rectangle.width * rectangle.height
}

