fn demonstrate_iterator_support() {
    println!("   🔄 **Iterator Support and Integration:**");

    // Implement iterator for our RingQueue
    struct IteratorRingQueue<T> {
        buffer: Vec<Option<T>>,
        head: usize,
        tail: usize,
        length: usize,
    }

    impl<T: Clone> IteratorRingQueue<T> {
        fn new(capacity: usize) -> Self {
            Self {
                buffer: vec![None; capacity],
                head: 0,
                tail: 0,
                length: 0,
            }
        }

        fn push_back(&mut self, item: T) -> Result<(), T> {
            if self.length == self.buffer.len() {
                return Err(item);
            }
            self.buffer[self.tail] = Some(item);
            self.tail = (self.tail + 1) % self.buffer.len();
            self.length += 1;
            Ok(())
        }

        fn len(&self) -> usize {
            self.length
        }

        fn is_empty(&self) -> bool {
            self.length == 0
        }

        fn capacity(&self) -> usize {
            self.buffer.len()
        }
    }

    // Iterator implementation
    struct RingQueueIter<'a, T> {
        queue: &'a IteratorRingQueue<T>,
        current: usize,
        remaining: usize,
    }

    impl<T: Clone> IteratorRingQueue<T> {
        fn iter(&self) -> RingQueueIter<T> {
            RingQueueIter {
                queue: self,
                current: self.head,
                remaining: self.length,
            }
        }
    }

    impl<'a, T: Clone> Iterator for RingQueueIter<'a, T> {
        type Item = &'a T;

        fn next(&mut self) -> Option<Self::Item> {
            if self.remaining == 0 {
                return None;
            }

            let item = self.queue.buffer[self.current].as_ref().unwrap();
            self.current = (self.current + 1) % self.queue.capacity();
            self.remaining -= 1;
            Some(item)
        }

        fn size_hint(&self) -> (usize, Option<usize>) {
            (self.remaining, Some(self.remaining))
        }
    }

    impl<'a, T: Clone> ExactSizeIterator for RingQueueIter<'a, T> {}

    // IntoIterator for references
    impl<'a, T: Clone> IntoIterator for &'a IteratorRingQueue<T> {
        type Item = &'a T;
        type IntoIter = RingQueueIter<'a, T>;

        fn into_iter(self) -> Self::IntoIter {
            self.iter()
        }
    }

