            Ok(None) => println!("❌ peek_mut returned None when it shouldn't"),
            Err(LinkedListError::BorrowConflict) => {
                println!("✅ peek_mut correctly reported borrow conflict")
            }
            Err(e) => println!("❌ peek_mut failed with unexpected error: {:?}", e),
        }
    }
}

