// Solution for Exercise 1: Basic Box Implementation
use std::fmt::Debug;

#[derive(Debug)]
struct Node<T> {
    data: T,
    next: Option<Box<Node<T>>>,
}

#[derive(Debug)]
pub struct SimpleLinkedList<T> {
    head: Option<Box<Node<T>>>,
    length: usize,
}

impl<T> SimpleLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            length: 0,
        }
    }
    
    pub fn push_front(&mut self, data: T) {
        let new_node = Box::new(Node {
            data,
            next: self.head.take(),
        });
        self.head = Some(new_node);
        self.length += 1;
    }
    
    pub fn pop_front(&mut self) -> Option<T> {
        self.head.take().map(|node| {
            self.head = node.next;
            self.length -= 1;
            node.data
        })
    }
    
    pub fn peek_front(&self) -> Option<&T> {
        self.head.as_ref().map(|node| &node.data)
    }
    
    pub fn len(&self) -> usize {
        self.length
    }
    
    pub fn is_empty(&self) -> bool {
        self.length == 0
    }
}

// Bonus implementations
impl<T: std::fmt::Display> SimpleLinkedList<T> {
    pub fn display(&self) {
        let mut current = &self.head;
        print!("List: ");
        
        while let Some(node) = current {
            print!("{}", node.data);
            current = &node.next;
            if current.is_some() {
                print!(" -> ");
            }
        }
        println!();
    }
}

impl<T> SimpleLinkedList<T> {
    // This is significantly more complex than push_front!
    pub fn push_back(&mut self, data: T) {
        if self.head.is_none() {
            self.push_front(data);
            return;
        }
        
        let new_node = Box::new(Node {
            data,
            next: None,
        });
        
        let mut current = self.head.as_mut().unwrap();
        while current.next.is_some() {
            current = current.next.as_mut().unwrap();
        }
        
        current.next = Some(new_node);
        self.length += 1;
    }
}

fn main() {
    let mut list = SimpleLinkedList::new();
    
    println!("=== Testing Basic Operations ===");
    
    // Test empty list
    assert!(list.is_empty());
    assert_eq!(list.len(), 0);
    assert_eq!(list.pop_front(), None);
    assert_eq!(list.peek_front(), None);
    
    // Test push_front
    list.push_front(1);
    list.push_front(2);
    list.push_front(3);
    
    assert!(!list.is_empty());
    assert_eq!(list.len(), 3);
    assert_eq!(list.peek_front(), Some(&3));
    
    // Test pop_front
    assert_eq!(list.pop_front(), Some(3));
    assert_eq!(list.len(), 2);
    assert_eq!(list.peek_front(), Some(&2));
    
    assert_eq!(list.pop_front(), Some(2));
    assert_eq!(list.pop_front(), Some(1));
    assert_eq!(list.pop_front(), None);
    
    assert!(list.is_empty());
    
    println!("✅ All tests passed!");
    
    // Test bonus features
    println!("\n=== Testing Bonus Features ===");
    
    list.push_front(1);
    list.push_front(2);
    list.push_front(3);
    list.display();
    
    list.push_back(0);
    list.display();
    
    println!("✅ Bonus features work!");
}

// Solution for Exercise 2: Rc<RefCell<T>> Patterns
use std::rc::Rc;
use std::cell::RefCell;

type NodeRef<T> = Rc<RefCell<RcNode<T>>>;

#[derive(Debug)]
struct RcNode<T> {
    data: T,
    next: Option<NodeRef<T>>,
}

#[derive(Debug)]
pub struct RcLinkedList<T> {
    head: Option<NodeRef<T>>,
    length: usize,
}

#[derive(Debug)]
pub enum LinkedListError {
    BorrowConflict,
    EmptyList,
    IndexOutOfBounds,
}

impl From<std::cell::BorrowError> for LinkedListError {
    fn from(_: std::cell::BorrowError) -> Self {
        LinkedListError::BorrowConflict
    }
}

impl From<std::cell::BorrowMutError> for LinkedListError {
    fn from(_: std::cell::BorrowMutError) -> Self {
        LinkedListError::BorrowConflict
    }
}

impl<T> RcLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            length: 0,
        }
    }
    
    pub fn push_front(&mut self, data: T) {
        let new_node = Rc::new(RefCell::new(RcNode {
            data,
            next: self.head.clone(), // Clone the Rc, not the data!
        }));
        self.head = Some(new_node);
        self.length += 1;
    }
    
    pub fn try_pop_front(&mut self) -> Result<Option<T>, LinkedListError> {
        match self.head.take() {
            Some(node) => {
                // Check if we have the only reference
                match Rc::try_unwrap(node) {
                    Ok(cell) => {
                        // We have exclusive access, safe to extract
                        let node_data = cell.into_inner();
                        self.head = node_data.next;
                        self.length -= 1;
                        Ok(Some(node_data.data))
                    }
                    Err(node) => {
                        // Other references exist, put the node back and return error
                        self.head = Some(node);
                        Err(LinkedListError::BorrowConflict)
                    }
                }
            }
            None => Ok(None),
        }
    }
    
    pub fn try_peek_front(&self) -> Result<Option<std::cell::Ref<T>>, LinkedListError> {
        match &self.head {
            Some(node) => {
                let borrowed = node.try_borrow()?;
                Ok(Some(std::cell::Ref::map(borrowed, |n| &n.data)))
            }
            None => Ok(None),
        }
    }
    
    pub fn try_peek_front_mut(&mut self) -> Result<Option<std::cell::RefMut<T>>, LinkedListError> {
        match &self.head {
            Some(node) => {
                let borrowed = node.try_borrow_mut()?;
                Ok(Some(std::cell::RefMut::map(borrowed, |n| &mut n.data)))
            }
            None => Ok(None),
        }
    }
    
    pub fn get_node_ref(&self, index: usize) -> Result<NodeRef<T>, LinkedListError> {
        if index >= self.length {
            return Err(LinkedListError::IndexOutOfBounds);
        }
        
        let mut current = self.head.clone().ok_or(LinkedListError::EmptyList)?;
        for _ in 0..index {
            let next = {
                let borrowed = current.try_borrow()?;
                borrowed.next.clone()
            };
            current = next.ok_or(LinkedListError::IndexOutOfBounds)?;
        }
        Ok(current)
    }
    
    pub fn len(&self) -> usize {
        self.length
    }
    
    pub fn is_empty(&self) -> bool {
        self.length == 0
    }
    
    // Bonus implementations
    pub fn insert_at(&mut self, index: usize, data: T) -> Result<(), LinkedListError> {
        if index > self.length {
            return Err(LinkedListError::IndexOutOfBounds);
        }
        
        if index == 0 {
            self.push_front(data);
            return Ok(());
        }
        
        let prev_node = self.get_node_ref(index - 1)?;
        let new_node = Rc::new(RefCell::new(RcNode {
            data,
            next: None,
        }));
        
        {
            let mut prev_borrow = prev_node.try_borrow_mut()?;
            new_node.borrow_mut().next = prev_borrow.next.clone();
            prev_borrow.next = Some(new_node);
        }
        
        self.length += 1;
        Ok(())
    }
    
    pub fn remove_at(&mut self, index: usize) -> Result<Option<T>, LinkedListError> {
        if index >= self.length {
            return Err(LinkedListError::IndexOutOfBounds);
        }
        
        if index == 0 {
            return self.try_pop_front();
        }
        
        let prev_node = self.get_node_ref(index - 1)?;
        let node_to_remove = {
            let prev_borrow = prev_node.try_borrow()?;
            prev_borrow.next.clone().ok_or(LinkedListError::IndexOutOfBounds)?
        };
        
        // Check if we can safely remove this node
        match Rc::try_unwrap(node_to_remove) {
            Ok(cell) => {
                let node_data = cell.into_inner();
                prev_node.try_borrow_mut()?.next = node_data.next;
                self.length -= 1;
                Ok(Some(node_data.data))
            }
            Err(_) => Err(LinkedListError::BorrowConflict),
        }
    }
}

// Advanced: Reference sharing demonstration
fn demonstrate_shared_references() -> Result<(), LinkedListError> {
    let mut list = RcLinkedList::new();
    
    // Add some data
    list.push_front("Third");
    list.push_front("Second");
    list.push_front("First");
    
    println!("=== Demonstrating Shared References ===");
    
    // Get references to different nodes
    let first_node = list.get_node_ref(0)?;
    let second_node = list.get_node_ref(1)?;
    
    println!("First node data: {:?}", first_node.try_borrow()?.data);
    println!("Second node data: {:?}", second_node.try_borrow()?.data);
    
    // We can hold multiple references to the same structure!
    println!("Reference count for first node: {}", Rc::strong_count(&first_node));
    
    // Demonstrate that they point to the same memory
    let first_addr = first_node.as_ptr();
    let first_again = list.get_node_ref(0)?;
    let first_again_addr = first_again.as_ptr();
    println!("Same memory address? {}", first_addr == first_again_addr);
    
    Ok(())
}

// Test borrow checking at runtime
fn demonstrate_borrow_conflicts() {
    let mut list = RcLinkedList::new();
    list.push_front(42);
    
    println!("=== Demonstrating Borrow Conflicts ===");
    
    // Get a node reference
    if let Ok(node_ref) = list.get_node_ref(0) {
        // Hold a mutable borrow
        let _mut_borrow = node_ref.borrow_mut();
        
        // Try to get another borrow - this should fail!
        match node_ref.try_borrow() {
            Ok(_) => println!("❌ This shouldn't work!"),
            Err(_) => println!("✅ Correctly caught borrow conflict (mut + immut)"),
        }
        
        // Try to get another mutable borrow - this should also fail!
        match node_ref.try_borrow_mut() {
            Ok(_) => println!("❌ This shouldn't work!"),
            Err(_) => println!("✅ Correctly caught borrow conflict (mut + mut)"),
        }
        
        // _mut_borrow is dropped here
    }
    
    // Now borrowing should work again
    if let Ok(node_ref) = list.get_node_ref(0) {
        match node_ref.try_borrow() {
            Ok(borrow) => println!("✅ Borrowing works after conflict resolved: {}", borrow.data),
            Err(_) => println!("❌ Should be able to borrow now"),
        }
    }
}

fn demonstrate_modification_through_shared_refs() -> Result<(), LinkedListError> {
    println!("=== Demonstrating Modification Through Shared References ===");
    
    let mut list = RcLinkedList::new();
    list.push_front(String::from("Original"));
    
    // Get a shared reference to the node
    let node_ref = list.get_node_ref(0)?;
    
    // Modify through the shared reference
    {
        let mut borrowed = node_ref.try_borrow_mut()?;
        borrowed.data.push_str(" - Modified!");
    }
    
    // Check that the modification is visible through the list
    if let Ok(Some(front)) = list.try_peek_front() {
        println!("Data after modification: {}", *front);
    }
    
    Ok(())
}

fn test_edge_cases() -> Result<(), LinkedListError> {
    println!("=== Testing Edge Cases ===");
    
    let mut list = RcLinkedList::new();
    
    // Test operations on empty list
    assert_eq!(list.try_pop_front()?, None);
    assert!(list.try_peek_front()?.is_none());
    assert!(list.get_node_ref(0).is_err());
    
    // Test single element
    list.push_front(42);
    assert_eq!(list.len(), 1);
    
    let node_ref = list.get_node_ref(0)?;
    assert_eq!(Rc::strong_count(&node_ref), 2); // list + our reference
    
    // Can't pop while we hold a reference
    assert!(list.try_pop_front().is_err());
    
    // Drop our reference
    drop(node_ref);
    
    // Now we can pop
    assert_eq!(list.try_pop_front()?, Some(42));
    assert_eq!(list.len(), 0);
    
    println!("✅ All edge cases passed!");
    Ok(())
}

fn main() -> Result<(), LinkedListError> {
    println!("=== Testing Rc<RefCell<T>> Implementation ===");
    
    let mut list = RcLinkedList::new();
    
    // Basic operations
    list.push_front(1);
    list.push_front(2);
    list.push_front(3);
    
    assert_eq!(list.len(), 3);
    
    // Test peeking
    if let Ok(Some(front)) = list.try_peek_front() {
        assert_eq!(*front, 3);
    }
    
    // Test popping (but first we need to ensure no shared references)
    assert_eq!(list.try_pop_front()?, Some(3));
    assert_eq!(list.len(), 2);
    
    println!("✅ Basic operations work!");
    
    // Demonstrate advanced features
    demonstrate_shared_references()?;
    demonstrate_borrow_conflicts();
    demonstrate_modification_through_shared_refs()?;
    test_edge_cases()?;
    
    // Test bonus features
    println!("=== Testing Bonus Features ===");
    let mut test_list = RcLinkedList::new();
    test_list.push_front(1);
    test_list.push_front(2);
    test_list.push_front(3);
    
    // Insert at position 1
    test_list.insert_at(1, 99)?;
    assert_eq!(test_list.len(), 4);
    
    // Remove from position 1
    assert_eq!(test_list.remove_at(1)?, Some(99));
    assert_eq!(test_list.len(), 3);
    
    println!("✅ Bonus features work!");
    
    Ok(())
}

// Solution for Exercise 3: Doubly Linked List with Weak References
use std::rc::{Rc, Weak};
use std::cell::RefCell;

type NodeRef<T> = Rc<RefCell<DoublyNode<T>>>;
type WeakNodeRef<T> = Weak<RefCell<DoublyNode<T>>>;

#[derive(Debug)]
struct DoublyNode<T> {
    data: T,
    next: Option<NodeRef<T>>,
    prev: Option<WeakNodeRef<T>>, // Weak reference to prevent cycles!
}

#[derive(Debug)]
pub struct DoublyLinkedList<T> {
    head: Option<NodeRef<T>>,
    tail: Option<WeakNodeRef<T>>, // Weak reference to tail
    length: usize,
}

#[derive(Debug)]
pub enum DoublyListError {
    BorrowConflict,
    EmptyList,
    InvalidReference,
}

impl From<std::cell::BorrowError> for DoublyListError {
    fn from(_: std::cell::BorrowError) -> Self {
        DoublyListError::BorrowConflict
    }
}

impl From<std::cell::BorrowMutError> for DoublyListError {
    fn from(_: std::cell::BorrowMutError) -> Self {
        DoublyListError::BorrowConflict
    }
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            length: 0,
        }
    }
    
    pub fn push_front(&mut self, data: T) -> Result<(), DoublyListError> {
        let new_node = Rc::new(RefCell::new(DoublyNode {
            data,
            next: None,
            prev: None,
        }));
        
        match &self.head {
            Some(old_head) => {
                // Link new_node -> old_head
                new_node.borrow_mut().next = Some(old_head.clone());
                // Link old_head <- new_node (weak reference)
                old_head.borrow_mut().prev = Some(Rc::downgrade(&new_node));
                // Update head
                self.head = Some(new_node);
            }
            None => {
                // First node in list
                self.head = Some(new_node.clone());
                self.tail = Some(Rc::downgrade(&new_node));
            }
        }
        
        self.length += 1;
        Ok(())
    }
    
    pub fn push_back(&mut self, data: T) -> Result<(), DoublyListError> {
        let new_node = Rc::new(RefCell::new(DoublyNode {
            data,
            next: None,
            prev: None,
        }));
        
        match &self.tail {
            Some(tail_weak) => {
                if let Some(old_tail) = tail_weak.upgrade() {
                    // Link old_tail -> new_node
                    old_tail.borrow_mut().next = Some(new_node.clone());
                    // Link new_node <- old_tail (weak reference)
                    new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
                    // Update tail
                    self.tail = Some(Rc::downgrade(&new_node));
                } else {
                    // Tail reference is stale, list is corrupted
                    return Err(DoublyListError::InvalidReference);
                }
            }
            None => {
                // First node in list
                self.head = Some(new_node.clone());
                self.tail = Some(Rc::downgrade(&new_node));
            }
        }
        
        self.length += 1;
        Ok(())
    }
    
    pub fn pop_front(&mut self) -> Result<Option<T>, DoublyListError> {
        match self.head.take() {
            Some(old_head) => {
                // Check if we can safely remove this node
                match Rc::try_unwrap(old_head) {
                    Ok(cell) => {
                        let node = cell.into_inner();
                        
                        match node.next {
                            Some(new_head) => {
                                // Clear the back-reference from new head
                                new_head.borrow_mut().prev = None;
                                self.head = Some(new_head);
                            }
                            None => {
                                // List is now empty
                                self.head = None;
                                self.tail = None;
                            }
                        }
                        
                        self.length -= 1;
                        Ok(Some(node.data))
                    }
                    Err(node) => {
                        // Other references exist, put the node back
                        self.head = Some(node);
                        Err(DoublyListError::BorrowConflict)
                    }
                }
            }
            None => Ok(None),
        }
    }
    
    pub fn pop_back(&mut self) -> Result<Option<T>, DoublyListError> {
        match &self.tail {
            Some(tail_weak) => {
                if let Some(tail_node) = tail_weak.upgrade() {
                    // Check if we can safely remove this node
                    match Rc::try_unwrap(tail_node) {
                        Ok(cell) => {
                            let node = cell.into_inner();
                            
                            match &node.prev {
                                Some(prev_weak) => {
                                    if let Some(new_tail) = prev_weak.upgrade() {
                                        // Clear the forward reference from new tail
                                        new_tail.borrow_mut().next = None;
                                        self.tail = Some(Rc::downgrade(&new_tail));
                                    } else {
                                        // Previous node is gone, list is corrupted
                                        return Err(DoublyListError::InvalidReference);
                                    }
                                }
                                None => {
                                    // This was the only node
                                    self.head = None;
                                    self.tail = None;
                                }
                            }
                            
                            self.length -= 1;
                            Ok(Some(node.data))
                        }
                        Err(node) => {
                            // Other references exist
                            Err(DoublyListError::BorrowConflict)
                        }
                    }
                } else {
                    // Tail reference is stale
                    Err(DoublyListError::InvalidReference)
                }
            }
            None => Ok(None),
        }
    }
    
    pub fn peek_front(&self) -> Result<Option<std::cell::Ref<T>>, DoublyListError> {
        match &self.head {
            Some(node) => {
                let borrowed = node.try_borrow()?;
                Ok(Some(std::cell::Ref::map(borrowed, |n| &n.data)))
            }
            None => Ok(None),
        }
    }
    
    pub fn peek_back(&self) -> Result<Option<std::cell::Ref<T>>, DoublyListError> {
        match &self.tail {
            Some(tail_weak) => {
                if let Some(tail_node) = tail_weak.upgrade() {
                    let borrowed = tail_node.try_borrow()?;
                    Ok(Some(std::cell::Ref::map(borrowed, |n| &n.data)))
                } else {
                    Err(DoublyListError::InvalidReference)
                }
            }
            None => Ok(None),
        }
    }
    
    // Bonus: Implement bidirectional iteration
    pub fn iter_forward(&self) -> ForwardIter<T> {
        ForwardIter {
            current: self.head.clone(),
        }
    }
    
    pub fn iter_backward(&self) -> BackwardIter<T> {
        BackwardIter {
            current: self.tail.clone(),
        }
    }
    
    pub fn len(&self) -> usize {
        self.length
    }
    
    pub fn is_empty(&self) -> bool {
        self.length == 0
    }
    
    // Additional utility methods
    pub fn get_node_at(&self, index: usize) -> Result<NodeRef<T>, DoublyListError> {
        if index >= self.length {
            return Err(DoublyListError::InvalidReference);
        }
        
        // Optimize: choose direction based on index
        if index < self.length / 2 {
            // Start from head
            let mut current = self.head.clone().ok_or(DoublyListError::EmptyList)?;
            for _ in 0..index {
                let next = {
                    let borrowed = current.try_borrow()?;
                    borrowed.next.clone()
                };
                current = next.ok_or(DoublyListError::InvalidReference)?;
            }
            Ok(current)
        } else {
            // Start from tail
            let mut current = self.tail
                .as_ref()
                .and_then(|w| w.upgrade())
                .ok_or(DoublyListError::EmptyList)?;
            
            for _ in 0..(self.length - 1 - index) {
                let prev = {
                    let borrowed = current.try_borrow()?;
                    borrowed.prev.as_ref().and_then(|w| w.upgrade())
                };
                current = prev.ok_or(DoublyListError::InvalidReference)?;
            }
            Ok(current)
        }
    }
    
    pub fn insert_at(&mut self, index: usize, data: T) -> Result<(), DoublyListError> {
        if index > self.length {
            return Err(DoublyListError::InvalidReference);
        }
        
        if index == 0 {
            return self.push_front(data);
        }
        
        if index == self.length {
            return self.push_back(data);
        }
        
        let new_node = Rc::new(RefCell::new(DoublyNode {
            data,
            next: None,
            prev: None,
        }));
        
        let next_node = self.get_node_at(index)?;
        let prev_node = {
            let borrowed = next_node.try_borrow()?;
            borrowed.prev.as_ref().and_then(|w| w.upgrade())
        }.ok_or(DoublyListError::InvalidReference)?;
        
        // Link: prev_node <-> new_node <-> next_node
        new_node.borrow_mut().next = Some(next_node.clone());
        new_node.borrow_mut().prev = Some(Rc::downgrade(&prev_node));
        
        prev_node.borrow_mut().next = Some(new_node.clone());
        next_node.borrow_mut().prev = Some(Rc::downgrade(&new_node));
        
        self.length += 1;
        Ok(())
    }
    
    pub fn remove_at(&mut self, index: usize) -> Result<Option<T>, DoublyListError> {
        if index >= self.length {
            return Err(DoublyListError::InvalidReference);
        }
        
        if index == 0 {
            return self.pop_front();
        }
        
        if index == self.length - 1 {
            return self.pop_back();
        }
        
        let node_to_remove = self.get_node_at(index)?;
        
        match Rc::try_unwrap(node_to_remove) {
            Ok(cell) => {
                let node = cell.into_inner();
                
                let prev_node = node.prev.as_ref().and_then(|w| w.upgrade())
                    .ok_or(DoublyListError::InvalidReference)?;
                let next_node = node.next.ok_or(DoublyListError::InvalidReference)?;
                
                // Link: prev_node <-> next_node (skip removed node)
                prev_node.borrow_mut().next = Some(next_node.clone());
                next_node.borrow_mut().prev = Some(Rc::downgrade(&prev_node));
                
                self.length -= 1;
                Ok(Some(node.data))
            }
            Err(_) => Err(DoublyListError::BorrowConflict),
        }
    }
    
    pub fn reverse(&mut self) -> Result<(), DoublyListError> {
        if self.length <= 1 {
            return Ok(());
        }
        
        // Swap head and tail
        let old_head = self.head.take();
        let old_tail_weak = self.tail.take();
        
        if let Some(old_tail) = old_tail_weak.and_then(|w| w.upgrade()) {
            self.head = Some(old_tail);
        }
        
        if let Some(ref old_head_node) = old_head {
            self.tail = Some(Rc::downgrade(old_head_node));
        }
        
        // Reverse all the links
        let mut current = old_head;
        while let Some(node) = current {
            let (next, prev) = {
                let mut borrowed = node.try_borrow_mut()?;
                // Swap next and prev
                let old_next = borrowed.next.take();
                let old_prev = borrowed.prev.take();
                
                borrowed.next = old_prev.and_then(|w| w.upgrade());
                borrowed.prev = old_next.as_ref().map(|n| Rc::downgrade(n));
                
                (old_next, old_prev)
            };
            current = next;
        }
        
        Ok(())
    }
}

// Forward iterator
pub struct ForwardIter<T> {
    current: Option<NodeRef<T>>,
}

impl<T> Iterator for ForwardIter<T>
where
    T: Clone,
{
    type Item = Result<T, DoublyListError>;
    
    fn next(&mut self) -> Option<Self::Item> {
        match self.current.take() {
            Some(node) => {
                match node.try_borrow() {
                    Ok(borrowed) => {
                        let data = borrowed.data.clone();
                        self.current = borrowed.next.clone();
                        Some(Ok(data))
                    }
                    Err(_) => Some(Err(DoublyListError::BorrowConflict)),
                }
            }
            None => None,
        }
    }
}

// Backward iterator
pub struct BackwardIter<T> {
    current: Option<WeakNodeRef<T>>,
}

impl<T> Iterator for BackwardIter<T>
where
    T: Clone,
{
    type Item = Result<T, DoublyListError>;
    
    fn next(&mut self) -> Option<Self::Item> {
        match self.current.take() {
            Some(weak_ref) => {
                match weak_ref.upgrade() {
                    Some(node) => {
                        match node.try_borrow() {
                            Ok(borrowed) => {
                                let data = borrowed.data.clone();
                                self.current = borrowed.prev.clone();
                                Some(Ok(data))
                            }
                            Err(_) => Some(Err(DoublyListError::BorrowConflict)),
                        }
                    }
                    None => Some(Err(DoublyListError::InvalidReference)),
                }
            }
            None => None,
        }
    }
}

// Helper function to demonstrate the power of doubly-linked lists
fn demonstrate_bidirectional_access() -> Result<(), DoublyListError> {
    let mut list = DoublyLinkedList::new();
    
    // Build a list: 1 <-> 2 <-> 3
    list.push_back(1)?;
    list.push_back(2)?;
    list.push_back(3)?;
    
    println!("=== Forward iteration ===");
    for item in list.iter_forward() {
        match item {
            Ok(data) => println!("Forward: {}", data),
            Err(e) => println!("Error: {:?}", e),
        }
    }
    
    println!("=== Backward iteration ===");
    for item in list.iter_backward() {
        match item {
            Ok(data) => println!("Backward: {}", data),
            Err(e) => println!("Error: {:?}", e),
        }
    }
    
