            );
        }
    }
}

use std::collections::HashMap;

/// Demonstrating the specific Dictionary wrapper methods you're using
fn main() {
    println!("🔬 Your Dictionary Wrapper - Method by Method Analysis");
    println!("======================================================\n");

    // Let's trace through what each wrapper method does

    println!("🏗️  1. BASIC FORWARDING METHODS");
    println!("===============================");
    println!("These methods just forward calls to the inner HashMap:");

    let mut raw_map = HashMap::new();
    raw_map.insert("key", "value");

    println!("  Dictionary.insert(key, value)");
    println!("    → self.inner.insert(key, value)  // Just forwards to HashMap");
    println!("  Dictionary.get(&key)");
    println!("    → self.inner.get(key)           // Just forwards to HashMap");
    println!("  Dictionary.len()");
    println!("    → self.inner.len()              // Just forwards to HashMap");

    println!("\n🎯 2. ENHANCED CONVENIENCE METHODS");
    println!("==================================");
    println!("These add new functionality not in HashMap:");

    println!("\n🔸 get_or_default() - No more unwrap_or!");

    // HashMap way (what you'd normally write):
    let default_score = 0;
    let score1 = raw_map.get("player1").copied().unwrap_or("default_value");
    println!(
        "  HashMap: map.get(\"player1\").copied().unwrap_or(\"default\") = {}",
        score1
    );

    // Dictionary way (cleaner):
    // dict.get_or_default(&"player1", 0)  // Much cleaner!
    println!("  Dictionary: dict.get_or_default(&\"player1\", 0)  // Much cleaner!");

    println!("\n🔸 insert_many() - Bulk insertion made easy!");

    // HashMap way (verbose):
    let mut map2 = HashMap::new();
    for (k, v) in [("a", 1), ("b", 2), ("c", 3)] {
        map2.insert(k, v);
    }
    println!("  HashMap: Manual loop over [(\"a\", 1), (\"b\", 2), (\"c\", 3)]");

    // Dictionary way (elegant):
    // dict.insert_many([("a", 1), ("b", 2), ("c", 3)])
    println!("  Dictionary: dict.insert_many([(\"a\", 1), (\"b\", 2), (\"c\", 3)])");

    println!("\n🔹 add_to_list() - Multi-value dictionary support!");

    // HashMap way (complex):
    let mut multi_map: HashMap<&str, Vec<String>> = HashMap::new();
    multi_map
        .entry("fruits")
        .or_insert_with(Vec::new)
        .push("apple".to_string());
    multi_map
        .entry("fruits")
        .or_insert_with(Vec::new)
        .push("banana".to_string());
    println!("  HashMap: map.entry(\"fruits\").or_insert_with(Vec::new).push(...)");

    // Dictionary way (simple):
    // dict.add_to_list("fruits", "apple")
    // dict.add_to_list("fruits", "banana")
    println!("  Dictionary: dict.add_to_list(\"fruits\", \"apple\")");

    println!("\n📊 3. THE WRAPPER PATTERN IN YOUR CODE");
    println!("=====================================");

    println!("Your Dictionary struct:");
    println!("  pub struct Dictionary<K, V> {{");
    println!("      inner: HashMap<K, V>,  // ← The actual HashMap");
    println!("  }}");

    println!("\nMethod forwarding example:");
    println!("  pub fn insert(&mut self, key: K, value: V) -> Option<V> {{");
    println!("      self.inner.insert(key, value)  // ← Forwards to HashMap");
    println!("  }}");

    println!("\nValue-added method example:");
    println!("  pub fn get_or_default(&self, key: &K, default: V) -> V {{");
    println!("      self.inner.get(key).cloned().unwrap_or(default)");
    println!("      // ↑ Uses HashMap but adds convenience");
    println!("  }}");

    println!("\n🎪 4. WHY THIS WRAPPER ROCKS");
    println!("============================");

    println!("✅ Advent of Code Benefits:");
    println!("   • get_or_default() - perfect for counters, default configs");
    println!("   • add_to_list() - multi-value mappings (word → anagrams)");
    println!("   • insert_many() - quick setup from parsed input");

    println!("\n✅ Development Benefits:");
    println!("   • Less boilerplate code");
    println!("   • Fewer bugs (no unwrap_or mistakes)");
    println!("   • Domain-specific methods");
    println!("   • All HashMap features still available");

    println!("\n🚀 5. ZERO-COST ABSTRACTION");
    println!("===========================");

    println!("At runtime:");
    println!("  Dictionary<String, i32>  ≡  HashMap<String, i32>");
    println!("  • Same memory layout");
    println!("  • Same performance");
    println!("  • Compiler optimizes away the wrapper");
    println!("  • You get convenience WITHOUT cost!");

    println!("\n🔍 The wrapper pattern is about:");
    println!("   📦 Taking existing functionality (HashMap)");
    println!("   🎁 Wrapping it in your own struct");
    println!("   ⚡ Adding domain-specific enhancements");
    println!("   🆓 While keeping all the original features");

    println!("\nYour Dictionary = HashMap + AoC-friendly convenience methods! 🦀");
}

// Eq vs PartialEq - Understanding the Difference
// A focused example showing why the distinction matters

use std::collections::HashMap;

fn main() {
    println!("=== Eq vs PartialEq Explained ===\n");

    // 1. PartialEq without Eq - Floating Point Example
    demo_partial_eq_without_eq();

    // 2. Both PartialEq and Eq - Integer Example
    demo_both_traits();

    // 3. Custom Type Example
    demo_custom_type();

    // 4. Why HashMap/HashSet need Eq
    demo_hash_collection_requirements();
}

fn demo_partial_eq_without_eq() {
    println!("1. PartialEq WITHOUT Eq - Floating Point Numbers:");

    let x = 42.0_f64;
    let y = 42.0_f64;
    let nan = f64::NAN;

    println!("   Regular numbers:");
    println!("   x = {}, y = {}", x, y);
    println!("   x == y: {}", x == y); // true - symmetric
    println!("   x == x: {}", x == x); // true - reflexive (for normal numbers)

    println!("\n   NaN breaks reflexivity:");
    println!("   NaN == NaN: {}", nan == nan); // false! Violates reflexivity
    println!("   NaN != NaN: {}", nan != nan); // true! This is weird but correct per IEEE 754

    println!("   ❌ f64 implements PartialEq but NOT Eq");
    println!("   ❌ Cannot use f64 as HashMap key because reflexivity is broken\n");
}

fn demo_both_traits() {
    println!("2. Both PartialEq AND Eq - Integer Example:");

    let x = 42_i32;
    let y = 42_i32;

    println!("   x = {}, y = {}", x, y);
    println!("   x == y: {}", x == y); // true - symmetric
    println!("   x == x: {}", x == x); // true - reflexive (always!)

    println!("   ✅ i32 implements both PartialEq AND Eq");
    println!("   ✅ Can use i32 as HashMap key because reflexivity is guaranteed\n");
}

fn demo_custom_type() {
    println!("3. Custom Type - Implementing Both Traits:");

    #[derive(Debug, PartialEq, Eq, Hash)]
    struct Person {
        id: u32,
        name: String,
    }

    let alice1 = Person {
        id: 1,
        name: "Alice".to_string(),
    };
    let alice2 = Person {
        id: 1,
        name: "Alice".to_string(),
    };
    let bob = Person {
        id: 2,
        name: "Bob".to_string(),
    };

    println!("   alice1 == alice2: {}", alice1 == alice2); // true
    println!("   alice1 == alice1: {}", alice1 == alice1); // true (reflexive)
    println!("   alice1 == bob: {}", alice1 == bob); // false

    println!("   ✅ Person implements both PartialEq and Eq");
    println!("   ✅ Can use Person in HashMap/HashSet\n");
}

fn demo_hash_collection_requirements() {
    println!("4. Why HashMap/HashSet Need Eq:");

    // This works - i32 has Eq
    let mut int_map: HashMap<i32, &str> = HashMap::new();
    int_map.insert(42, "answer");
    println!("   ✅ HashMap<i32, &str> works fine");

    // This would NOT compile - f64 lacks Eq
    // let mut float_map: HashMap<f64, &str> = HashMap::new();  // Compile error!
    println!("   ❌ HashMap<f64, &str> won't compile - f64 lacks Eq trait");

    println!("\n   Why Eq is required for hash collections:");
    println!("   - Hash invariant: if a == b, then hash(a) == hash(b)");
    println!("   - This requires reflexive equality (x == x must always be true)");
    println!("   - f64::NAN violates this, so f64 can't implement Eq");
    println!("   - Without Eq, HashMap can't guarantee correct behavior");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_eq_vs_partial_eq_understanding() {
        // f64 implements PartialEq but not Eq
        let x = 42.0_f64;
        assert_eq!(x, 42.0); // PartialEq works

        let nan = f64::NAN;
        assert_ne!(nan, nan); // NaN is not equal to itself!

        // i32 implements both PartialEq and Eq
        let y = 42_i32;
        assert_eq!(y, 42); // PartialEq works
        assert_eq!(y, y); // Reflexivity guaranteed by Eq
    }

    #[test]
    fn test_hash_map_with_eq_types() {
        use std::collections::HashMap;

        // This compiles because i32 implements Eq
        let mut map: HashMap<i32, &str> = HashMap::new();
        map.insert(1, "one");
        map.insert(2, "two");

        assert_eq!(map.get(&1), Some(&"one"));
        assert_eq!(map.get(&2), Some(&"two"));
    }
}

// File Reading and Line Processing Patterns in Rust
// =================================================

use anyhow::Result;
use std::fs;
use std::io::{self, BufRead, BufReader};

fn main() -> Result<()> {
    println!("📁 File Reading Patterns in Rust");
    println!("=================================");

    // Create a sample file for demonstration
    create_sample_file()?;

    // Pattern 1: Read entire file as string, then split lines
    pattern1_read_all_then_split()?;

    // Pattern 2: Read file using BufReader (memory efficient for large files)
    pattern2_buffered_reader()?;

    // Pattern 3: AoC-style processing (most common pattern)
    pattern3_aoc_style()?;

    // Pattern 4: Collecting lines into Vec<String>
    pattern4_collect_lines()?;

    // Pattern 5: Processing with error handling
    pattern5_with_error_handling()?;

    Ok(())
}

fn create_sample_file() -> Result<()> {
    let content = "ugknbfddgicrmopn
aaa
jchzalrnumimnmhp  
haegwjzuvuyypxyu
dvszwmarrgswjxmb
line with spaces
another line
final line";

    fs::write("sample.txt", content)?;
    println!("✅ Created sample.txt for demonstration\n");
    Ok(())
}

/// Pattern 1: Read entire file as string, then split lines
/// ✅ Simple and common for small files
/// ❌ Loads entire file into memory
fn pattern1_read_all_then_split() -> Result<()> {
    println!("🎯 Pattern 1: Read all, then split lines");
    println!("----------------------------------------");

    // Read entire file as a single string
    let input = fs::read_to_string("sample.txt")?;

    // Split into lines and process
    let lines: Vec<&str> = input.lines().collect();

    println!("Total lines: {}", lines.len());
    for (i, line) in lines.iter().enumerate() {
        println!("Line {}: '{}'", i + 1, line);
    }

    // Alternative: process directly without collecting
    println!("\nDirect processing:");
    let nice_count = input.lines().filter(|line| is_nice_demo(line)).count();

    println!("Nice strings: {}\n", nice_count);
    Ok(())
}

/// Pattern 2: BufReader for memory-efficient line-by-line reading
/// ✅ Memory efficient for large files
/// ✅ Can handle very large files
/// ❌ Slightly more complex
fn pattern2_buffered_reader() -> Result<()> {
    println!("🎯 Pattern 2: Buffered Reader (memory efficient)");
    println!("-----------------------------------------------");

    let file = std::fs::File::open("sample.txt")?;
    let reader = BufReader::new(file);

    let mut nice_count = 0;
    let mut total_lines = 0;

    for line_result in reader.lines() {
        let line = line_result?; // Handle potential I/O errors
        total_lines += 1;

        println!("Processing: '{}'", line);
        if is_nice_demo(&line) {
            nice_count += 1;
        }
    }

    println!("Processed {} lines, {} are nice\n", total_lines, nice_count);
    Ok(())
}

/// Pattern 3: AoC-style processing (most common for competitive programming)
/// ✅ Simple and efficient for typical AoC inputs
/// ✅ Easy to understand and modify
fn pattern3_aoc_style() -> Result<()> {
    println!("🎯 Pattern 3: AoC-style (recommended for competitions)");
    println!("----------------------------------------------------");

    let input = fs::read_to_string("sample.txt")?;

    // This is the pattern you see in most AoC solutions
    let result = input
        .lines() // Iterator over lines
        .filter(|line| !line.is_empty()) // Skip empty lines
        .filter(|line| is_nice_demo(line)) // Apply your logic
        .count(); // Count matches

    println!("AoC-style result: {} nice strings", result);

    // More complex example: collecting and processing
    let processed_lines: Vec<String> = input
        .lines()
        .map(|line| line.trim()) // Remove whitespace
        .filter(|line| !line.is_empty()) // Skip empty lines
        .map(|line| format!("Processed: {}", line)) // Transform
        .collect();

    println!("Processed {} lines:", processed_lines.len());
    for line in &processed_lines[0..3] {
        // Show first 3
        println!("  {}", line);
    }
    println!();

    Ok(())
}

/// Pattern 4: Collecting lines for multiple passes
/// ✅ Good when you need to process the same data multiple times
/// ❌ Uses more memory
fn pattern4_collect_lines() -> Result<()> {
    println!("🎯 Pattern 4: Collect lines into Vec<String>");
    println!("--------------------------------------------");

    let input = fs::read_to_string("sample.txt")?;

    // Collect all lines into owned strings
    let lines: Vec<String> = input
        .lines()
        .map(|line| line.trim().to_string()) // Convert to owned String
        .filter(|line| !line.is_empty()) // Skip empty lines
        .collect();

    println!("Collected {} lines", lines.len());

    // Now you can do multiple passes
    let total_chars: usize = lines.iter().map(|line| line.len()).sum();
    let nice_count = lines.iter().filter(|line| is_nice_demo(line)).count();
    let long_lines = lines.iter().filter(|line| line.len() > 10).count();

    println!("Total characters: {}", total_chars);
    println!("Nice strings: {}", nice_count);
    println!("Long lines (>10 chars): {}", long_lines);
    println!();

    Ok(())
}

/// Pattern 5: With comprehensive error handling
/// ✅ Production-ready error handling
/// ✅ Handles various failure modes
fn pattern5_with_error_handling() -> Result<()> {
    println!("🎯 Pattern 5: With error handling");
    println!("---------------------------------");

    // Check if file exists first
    if !std::path::Path::new("sample.txt").exists() {
        println!("❌ File doesn't exist!");
        return Ok(());
    }

    // Read with proper error handling
    match fs::read_to_string("sample.txt") {
        Ok(content) => {
            println!("✅ File read successfully");

            let results: Result<Vec<_>, _> = content
                .lines()
                .enumerate()
                .map(|(i, line)| -> Result<String> {
                    if line.is_empty() {
                        return Err(anyhow::anyhow!("Empty line at line {}", i + 1));
                    }

                    Ok(format!("Line {}: {} chars", i + 1, line.len()))
                })
                .collect();

            match results {
                Ok(processed) => {
                    println!("Successfully processed {} lines", processed.len());
                    for result in &processed[0..3] {
                        // Show first 3
                        println!("  {}", result);
                    }
                }
                Err(e) => println!("❌ Processing error: {}", e),
            }
        }
        Err(e) => println!("❌ Failed to read file: {}", e),
    }

    println!();
    Ok(())
}

// Demo function for AoC Day 5 logic
fn is_nice_demo(s: &str) -> bool {
    let vowel_count = s.chars().filter(|&c| "aeiou".contains(c)).count();
    let has_double = s.chars().zip(s.chars().skip(1)).any(|(a, b)| a == b);
    let forbidden = ["ab", "cd", "pq", "xy"];
    let has_forbidden = forbidden.iter().any(|&bad| s.contains(bad));

    vowel_count >= 3 && has_double && !has_forbidden
}

//! # Final Project: Comprehensive Hash Data Structures System
//!
//! **Objective**: Build a complete application combining all learned patterns
//!
//! **Time Estimate**: 20 minutes to understand, practice as long as needed
//!
//! **What This Demonstrates**:
//! - Integration of all HashMap and HashSet patterns
//! - Real-world application architecture
//! - Performance optimization with caching
//! - AoC-style problem solving
//! - Production-ready error handling

use std::collections::{HashMap, HashSet};
use std::time::Instant;

/// Comprehensive Text Analysis System
/// Combines frequency counting, caching, and set operations
#[derive(Debug)]
pub struct TextAnalysisEngine {
    // Core data structures
    word_frequencies: HashMap<String, usize>,
    document_index: HashMap<String, HashSet<String>>, // word -> document_ids
    document_content: HashMap<String, String>,

    // Caching layer
    analysis_cache: HashMap<String, AnalysisResult>,

    // Statistics
    total_documents: usize,
    total_words: usize,
    cache_hits: usize,
    cache_misses: usize,
}

#[derive(Debug, Clone)]
pub struct AnalysisResult {
    word_count: usize,
    unique_words: usize,
    most_common_words: Vec<(String, usize)>,
    readability_score: f32,
    computed_at: Instant,
}

impl TextAnalysisEngine {
    pub fn new() -> Self {
        TextAnalysisEngine {
            word_frequencies: HashMap::new(),
            document_index: HashMap::new(),
            document_content: HashMap::new(),
            analysis_cache: HashMap::new(),
            total_documents: 0,
            total_words: 0,
            cache_hits: 0,
            cache_misses: 0,
        }
    }

    /// Add a document to the analysis engine
    pub fn add_document(&mut self, doc_id: String, content: String) {
        println!("📄 Adding document: {}", doc_id);

        // Store content
        self.document_content
            .insert(doc_id.clone(), content.clone());

        // Process words
        let words: Vec<String> = content
            .to_lowercase()
            .split_whitespace()
            .map(|word| word.trim_matches(|c: char| !c.is_alphabetic()))
            .filter(|word| !word.is_empty())
            .map(|word| word.to_string())
            .collect();

        // Update frequency counters
        for word in &words {
            *self.word_frequencies.entry(word.clone()).or_insert(0) += 1;
            self.document_index
                .entry(word.clone())
                .or_insert_with(HashSet::new)
                .insert(doc_id.clone());
        }

        self.total_words += words.len();
        self.total_documents += 1;

        // Invalidate cache for this document
        self.analysis_cache.remove(&doc_id);

        println!("  ✅ Processed {} words", words.len());
    }

    /// Perform comprehensive analysis with caching
    pub fn analyze_document(&mut self, doc_id: &str) -> Option<AnalysisResult> {
        // Check cache first
        if let Some(cached_result) = self.analysis_cache.get(doc_id) {
            self.cache_hits += 1;
            println!("  📄 Cache HIT for {}", doc_id);
            return Some(cached_result.clone());
        }

        self.cache_misses += 1;
        println!("  🔄 Cache MISS - analyzing {}", doc_id);

        // Get document content
        let content = self.document_content.get(doc_id)?;

        // Perform analysis
        let words: Vec<String> = content
            .to_lowercase()
            .split_whitespace()
            .map(|word| word.trim_matches(|c: char| !c.is_alphabetic()))
            .filter(|word| !word.is_empty())
            .map(|word| word.to_string())
            .collect();

        let word_count = words.len();
        let unique_words: HashSet<_> = words.iter().collect();
        let unique_count = unique_words.len();

        // Find most common words in this document
        let mut word_freq_local = HashMap::new();
        for word in &words {
            *word_freq_local.entry(word.clone()).or_insert(0) += 1;
        }

        let mut most_common: Vec<_> = word_freq_local.into_iter().collect();
        most_common.sort_by_key(|(_, count)| std::cmp::Reverse(*count));
        most_common.truncate(5);

        // Calculate simple readability score
        let avg_word_length = if word_count > 0 {
            words.iter().map(|w| w.len()).sum::<usize>() as f32 / word_count as f32
        } else {
            0.0
        };
        let vocabulary_richness = if word_count > 0 {
            unique_count as f32 / word_count as f32
        } else {
            0.0
        };
        let readability_score = (avg_word_length * 10.0) + (vocabulary_richness * 100.0);

        let result = AnalysisResult {
            word_count,
            unique_words: unique_count,
            most_common_words: most_common,
            readability_score,
            computed_at: Instant::now(),
        };

        // Cache the result
        self.analysis_cache
            .insert(doc_id.to_string(), result.clone());

        Some(result)
    }

    /// Search for documents containing specific words
    pub fn search_documents(&self, query_words: &[&str]) -> Vec<String> {
        if query_words.is_empty() {
            return Vec::new();
        }

        // Start with documents containing the first word
        let mut result_docs = if let Some(docs) = self.document_index.get(query_words[0]) {
            docs.clone()
        } else {
            return Vec::new();
        };

        // Intersect with documents containing each additional word
        for &word in &query_words[1..] {
            if let Some(docs) = self.document_index.get(word) {
                result_docs = result_docs.intersection(docs).cloned().collect();
            } else {
                return Vec::new(); // No documents contain this word
            }
        }

        result_docs.into_iter().collect()
    }

    /// Find similar documents based on word overlap
    pub fn find_similar_documents(&self, doc_id: &str, threshold: f32) -> Vec<(String, f32)> {
        let doc_words = if let Some(content) = self.document_content.get(doc_id) {
            content
                .to_lowercase()
                .split_whitespace()
                .map(|word| word.trim_matches(|c: char| !c.is_alphabetic()))
                .filter(|word| !word.is_empty())
                .map(|word| word.to_string())
                .collect::<HashSet<String>>()
        } else {
            return Vec::new();
        };

        let mut similarities = Vec::new();

        for (other_doc_id, other_content) in &self.document_content {
            if other_doc_id == doc_id {
                continue;
            }

            let other_words: HashSet<String> = other_content
                .to_lowercase()
                .split_whitespace()
                .map(|word| word.trim_matches(|c: char| !c.is_alphabetic()))
                .filter(|word| !word.is_empty())
                .map(|word| word.to_string())
                .collect();

            // Calculate Jaccard similarity
            let intersection = doc_words.intersection(&other_words).count();
            let union = doc_words.union(&other_words).count();

            let similarity = if union > 0 {
                intersection as f32 / union as f32
            } else {
                0.0
            };

            if similarity >= threshold {
                similarities.push((other_doc_id.clone(), similarity));
            }
        }

        similarities.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        similarities
    }

    /// Get comprehensive system statistics
    pub fn get_statistics(&self) -> SystemStats {
        SystemStats {
            total_documents: self.total_documents,
            total_words: self.total_words,
            unique_words: self.word_frequencies.len(),
            cache_hits: self.cache_hits,
            cache_misses: self.cache_misses,
            cache_hit_ratio: if self.cache_hits + self.cache_misses > 0 {
                self.cache_hits as f32 / (self.cache_hits + self.cache_misses) as f32
            } else {
                0.0
            },
            top_words: {
                let mut words: Vec<_> = self.word_frequencies.iter().collect();
                words.sort_by_key(|(_, count)| std::cmp::Reverse(**count));
                words
                    .into_iter()
                    .take(10)
                    .map(|(word, count)| (word.clone(), *count))
                    .collect()
            },
        }
    }
}

#[derive(Debug)]
pub struct SystemStats {
    pub total_documents: usize,
    pub total_words: usize,
    pub unique_words: usize,
    pub cache_hits: usize,
    pub cache_misses: usize,
    pub cache_hit_ratio: f32,
    pub top_words: Vec<(String, usize)>,
}

/// Coordinate-based Game State System
/// Demonstrates HashMap for spatial data and game logic
#[derive(Debug)]
pub struct GameWorld {
    grid: HashMap<(i32, i32), CellType>,
    entities: HashMap<String, (i32, i32)>,
    visited_positions: HashSet<(i32, i32)>,
    path_cache: HashMap<((i32, i32), (i32, i32)), Option<Vec<(i32, i32)>>>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum CellType {
    Empty,
    Wall,
    Treasure,
    Monster,
    Player,
}

impl GameWorld {
    pub fn new() -> Self {
        GameWorld {
            grid: HashMap::new(),
            entities: HashMap::new(),
            visited_positions: HashSet::new(),
            path_cache: HashMap::new(),
        }
    }

    pub fn set_cell(&mut self, pos: (i32, i32), cell_type: CellType) {
        self.grid.insert(pos, cell_type);
    }

    pub fn move_entity(&mut self, entity_id: &str, new_pos: (i32, i32)) -> bool {
        // Check if move is valid
        if let Some(cell) = self.grid.get(&new_pos) {
            if *cell == CellType::Wall {
                return false;
            }
        }

        // Update entity position
        self.entities.insert(entity_id.to_string(), new_pos);
        self.visited_positions.insert(new_pos);

        // Clear path cache (positions changed)
        self.path_cache.clear();

        true
    }

    pub fn find_entities_in_radius(
        &self,
        center: (i32, i32),
        radius: i32,
    ) -> Vec<(String, (i32, i32))> {
        self.entities
            .iter()
            .filter(|(_, &(x, y))| {
                let dx = (x - center.0).abs();
                let dy = (y - center.1).abs();
                dx <= radius && dy <= radius
            })
            .map(|(id, &pos)| (id.clone(), pos))
            .collect()
    }

    pub fn get_exploration_stats(&self) -> (usize, f32) {
        let total_accessible = self
            .grid
            .iter()
            .filter(|(_, cell)| **cell != CellType::Wall)
            .count();

        let visited_count = self.visited_positions.len();
        let exploration_percentage = if total_accessible > 0 {
            visited_count as f32 / total_accessible as f32 * 100.0
        } else {
            0.0
        };

        (visited_count, exploration_percentage)
    }
}

