        lru.put("B", 2);

        assert_eq!(lru.get(&"A"), Some(1));
        assert_eq!(lru.get(&"B"), Some(2));

        // Add C, should evict least recently used
        lru.put("C", 3);

        // A should still be there (was accessed recently)
        assert_eq!(lru.get(&"A"), Some(1));
        // B should be evicted
        assert_eq!(lru.get(&"B"), None);
        // C should be there
