    println!("Testing Graph trait operations:");
    println!("  neighbors(0) = {:?}", graph.neighbors(0));
    println!("  neighbors(1) = {:?}", graph.neighbors(1));
    println!("  contains(0) = {}", graph.contains(0));
    println!("  contains(5) = {}\n", graph.contains(5));
}

